import type { FileManagerFileTypeInput } from '@components/file-type-registry/file-manager-file-type-types';
import { getFileManager } from '@components/file-viewer/file-manager-registry';
import type { FileManagerFileStat } from './file-manager-types';

export function normalizeFileManagerPath(path: string): string {
	const parts: string[] = [];
	for (const part of path.replaceAll('\\', '/').split('/')) {
		if (!part || part === '.') continue;
		if (part === '..') {
			parts.pop();
			continue;
		}
		parts.push(part);
	}
	return `/${parts.join('/')}`;
}

export function joinFileManagerPath(directory: string, name: string): string {
	return normalizeFileManagerPath(`${directory}/${name}`);
}

export function getFileManagerParentPath(path: string): string {
	const normalized = normalizeFileManagerPath(path);
	if (normalized === '/') return '/';
	const index = normalized.lastIndexOf('/');
	return index <= 0 ? '/' : normalized.slice(0, index);
}

export function getFileManagerBasename(path: string): string {
	const normalized = normalizeFileManagerPath(path);
	return normalized === '/' ? '' : normalized.slice(normalized.lastIndexOf('/') + 1);
}

export function isFileManagerPathWithinRoot(path: string, rootPath: string): boolean {
	const normalizedPath = normalizeFileManagerPath(path);
	const normalizedRoot = normalizeFileManagerPath(rootPath);
	return normalizedRoot === '/' || normalizedPath === normalizedRoot || normalizedPath.startsWith(`${normalizedRoot}/`);
}

export function isFileManagerDescendantPath(sourcePath: string, targetPath: string): boolean {
	const source = normalizeFileManagerPath(sourcePath);
	const target = normalizeFileManagerPath(targetPath);
	return source === '/' ? target !== '/' : target.startsWith(`${source}/`);
}

export function validateFileManagerName(name: string): string | undefined {
	const value = name.trim();
	if (!value) return '名称不能为空';
	if (value === '.' || value === '..') return '名称不能是 . 或 ..';
	if (value.includes('/') || value.includes('\\') || value.includes('\0')) return '名称不能包含路径分隔符';
	return undefined;
}

export function sortFileManagerEntries(
	entries: readonly FileManagerFileStat[],
	options: { by: 'name' | 'size' | 'mtime'; direction: 'asc' | 'desc' },
): FileManagerFileStat[] {
	const direction = options.direction === 'asc' ? 1 : -1;
	return [...entries].sort((left, right) => {
		if (left.kind !== right.kind) return left.kind === 'directory' ? -1 : 1;
		if (options.by === 'size' && left.size !== right.size) return (left.size - right.size) * direction;
		if (options.by === 'mtime' && left.mtime !== right.mtime) return (left.mtime - right.mtime) * direction;
		return left.name.localeCompare(right.name, undefined, { numeric: true, sensitivity: 'base' }) * direction;
	});
}

export function formatFileManagerBytes(bytes: number): string {
	if (!Number.isFinite(bytes) || bytes <= 0) return '0 B';
	const units = ['B', 'KB', 'MB', 'GB', 'TB'];
	const index = Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), units.length - 1);
	const value = bytes / 1024 ** index;
	return `${value.toFixed(index === 0 || value >= 10 ? 0 : 1)} ${units[index]}`;
}

export function getFileManagerExtension(name: string): string {
	const dot = name.lastIndexOf('.');
	return dot <= 0 ? '' : name.slice(dot + 1).toLowerCase();
}

export function getFileManagerMimeType(entry: Pick<FileManagerFileStat, 'meta'>): string | undefined {
	for (const key of ['mimeType', 'type', 'contentType']) {
		if (Object.hasOwn(entry.meta, key) && typeof entry.meta[key] === 'string') return entry.meta[key];
	}
	return undefined;
}

export function toFileManagerFileTypeInput(entry: FileManagerFileStat): FileManagerFileTypeInput {
	return {
		extension: getFileManagerExtension(entry.name),
		kind: entry.kind,
		lastModified: entry.mtime,
		meta: entry.meta,
		mimeType: getFileManagerMimeType(entry),
		name: entry.name,
		path: entry.path,
		size: entry.size,
	};
}

export function isFileManagerTextFile(name: string): boolean {
	return getFileManager().fileTypes.resolve({ name, kind: 'file' })?.viewerKind === 'text';
}

export function getFileManagerMediaKind(name: string): 'audio' | 'binary' | 'image' | 'pdf' | 'text' | 'video' {
	const kind = getFileManager().fileTypes.resolve({ name, kind: 'file' })?.viewerKind;
	return kind && kind !== 'unsupported' ? kind : 'binary';
}

export function sanitizeFileManagerStat(entry: FileManagerFileStat, safePath: string): FileManagerFileStat {
	const path = normalizeFileManagerPath(safePath);
	if (entry.kind !== 'directory' && entry.kind !== 'file') throw new Error(`文件系统返回了非法项目类型：${path}`);
	return {
		directory: getFileManagerParentPath(path),
		kind: entry.kind,
		meta: entry.meta ?? {},
		mtime: Number.isFinite(entry.mtime) ? entry.mtime : 0,
		name: getFileManagerBasename(path),
		path,
		size: Number.isFinite(entry.size) && entry.size > 0 ? entry.size : 0,
	};
}

import type { FileManagerRegistry } from '@components/file-type-registry/file-manager-file-type-types';
import type Emittery from 'emittery';
import type { ReactNode } from 'react';

export const fileManagerUploadHardFileLimit = 4_096;
export const fileManagerListingHardEntryLimit = 10_000;
export const fileManagerOperationHardItemLimit = 4_096;

export type FileManagerFileStat = {
	directory: string;
	kind: 'directory' | 'file';
	meta: Record<string, unknown>;
	mtime: number;
	name: string;
	path: string;
	size: number;
};

export type FileManagerFileSystem = {
	copy(
		source: string,
		destination: string,
		options?: { overwrite?: boolean; shallow?: boolean; signal?: AbortSignal },
	): Promise<void>;
	getUrl?(path: FileManagerFileStat | string): string | undefined;
	exists(path: string): Promise<boolean>;
	mkdir(path: string, options?: { recursive?: boolean; signal?: AbortSignal }): Promise<void>;
	readFile(path: string, options: { encoding: 'text'; maxBytes?: number; signal?: AbortSignal }): Promise<string>;
	readFile(
		path: string,
		options?: { encoding?: 'binary'; maxBytes?: number; signal?: AbortSignal },
	): Promise<Uint8Array>;
	readdir(path: string, options?: { signal?: AbortSignal }): Promise<FileManagerFileStat[]>;
	rename(source: string, destination: string, options?: { overwrite?: boolean; signal?: AbortSignal }): Promise<void>;
	rm(path: string, options?: { force?: boolean; recursive?: boolean; signal?: AbortSignal }): Promise<void>;
	stat(path: string, options?: { signal?: AbortSignal }): Promise<FileManagerFileStat>;
	writeFile(
		path: string,
		data: string | ArrayBuffer | ArrayBufferView<ArrayBufferLike> | ReadableStream,
		options?: { overwrite?: boolean; signal?: AbortSignal },
	): Promise<void>;
};

export type FileManagerViewMode = 'list' | 'grid';
export type FileManagerSortBy = 'name' | 'size' | 'mtime';
export type FileManagerSortDirection = 'asc' | 'desc';

export type FileManagerCapabilities = {
	copy: boolean;
	createDirectory: boolean;
	createFile: boolean;
	delete: boolean;
	download: boolean;
	edit: boolean;
	move: boolean;
	preview: boolean;
	rename: boolean;
	upload: boolean;
};

export const defaultFileManagerCapabilities: FileManagerCapabilities = {
	copy: true,
	createDirectory: true,
	createFile: true,
	delete: true,
	download: true,
	edit: true,
	move: true,
	preview: true,
	rename: true,
	upload: true,
};

export type FileManagerPlace = {
	id: string;
	label: ReactNode;
	path: string;
	icon?: ReactNode;
};

export type FileManagerDialogState =
	| { type: 'create'; kind: 'directory' | 'file'; value: string }
	| { type: 'delete' }
	| { type: 'rename'; value: string }
	| { type: 'transfer'; mode: 'copy' | 'move'; destination: string }
	| null;

export type FileManagerOperation =
	| { type: 'copy'; paths: string[]; destination: string }
	| { type: 'create-directory'; directory: string; name: string }
	| { type: 'create-file'; directory: string; name: string }
	| { type: 'delete'; paths: string[] }
	| { type: 'download'; paths: string[] }
	| { type: 'move'; paths: string[]; destination: string }
	| { type: 'rename'; path: string; name: string }
	| { type: 'save-text'; path: string; content: string }
	| {
			type: 'upload';
			directory: string;
			files: File[];
			rejected?: Array<{ name: string; reason: 'directory' | 'too-many' | 'unreadable' }>;
	  };

export type FileManagerHistoryMode =
	| { type: 'push' }
	| { type: 'replace' }
	| { type: 'traverse'; index: number }
	| { type: 'none' };

export type FileManagerRequest =
	| { type: 'cancel-operation'; fileSystem: FileManagerFileSystem; requestId: number }
	| { type: 'load'; path: string; history: FileManagerHistoryMode }
	| {
			type: 'open';
			directory: string;
			entry: FileManagerFileStat;
			fileSystem: FileManagerFileSystem;
			listingRequestId: number;
			rootPath: string;
	  }
	| {
			type: 'operation';
			fileSystem: FileManagerFileSystem;
			operation: FileManagerOperation;
			requestId: number;
			rootPath: string;
	  };

export type FileManagerEvent =
	| { type: 'error'; action: string; error: unknown }
	| { type: 'navigated'; path: string }
	| { type: 'open-failed'; entry: FileManagerFileStat; error: unknown }
	| { type: 'opened'; entry: FileManagerFileStat }
	| {
			type: 'operation-cancelled';
			operation: FileManagerOperation;
			reason: 'aborted' | 'backend-changed';
			result?: FileManagerOperationResult;
	  }
	| { type: 'operation-failed'; operation: FileManagerOperation; error: unknown; result?: FileManagerOperationResult }
	| { type: 'operation-started'; operation: FileManagerOperation }
	| { type: 'operation-succeeded'; operation: FileManagerOperation; result: FileManagerOperationResult }
	| { type: 'selection-changed'; paths: string[] };

export type FileManagerOperationResult = {
	completed: string[];
	failed: Array<{ path: string; error: unknown }>;
};

export type FileManagerOperationOutcome = 'cancelled' | 'failed' | 'succeeded';

export type FileManagerOperationFeedback = {
	error?: unknown;
	operation: FileManagerOperation;
	outcome: FileManagerOperationOutcome;
	result?: FileManagerOperationResult;
};

export type FileManagerEventMap = {
	event: FileManagerEvent;
	request: FileManagerRequest;
};

export type FileManagerStoreState = {
	fileSystem: FileManagerFileSystem;
	rootPath: string;
	capabilities: FileManagerCapabilities;
	navigation: {
		path: string;
		address: string;
		history: string[];
		index: number;
	};
	listing: {
		entries: FileManagerFileStat[];
		status: 'idle' | 'loading' | 'ready' | 'error';
		error?: string;
		requestId: number;
		requestedPath?: string;
	};
	selection: {
		paths: string[];
		anchorPath?: string;
	};
	view: {
		mode: FileManagerViewMode;
		previewOpen: boolean;
		query: string;
		sidebarOpen: boolean;
		sortBy: FileManagerSortBy;
		sortDirection: FileManagerSortDirection;
	};
	operation: {
		status: 'idle' | 'running' | 'error';
		active?: FileManagerOperation;
		activeRequestId?: number;
		feedback?: FileManagerOperationFeedback;
		kind?: FileManagerOperation['type'];
		nextRequestId: number;
		notice?: string;
		error?: string;
	};
	preview: {
		draft?: { content: string; path: string };
		pendingSavePath?: string;
		saveError?: { message: string; path: string };
	};
	dialog: FileManagerDialogState;
	events: Emittery<FileManagerEventMap>;
	actions: FileManagerActions;
};

export type FileManagerActions = {
	back: () => void;
	beginListing: (path: string) => number;
	cancelOperation: () => void;
	clearError: () => void;
	closeDialog: () => void;
	completeListing: (
		requestId: number,
		path: string,
		entries: FileManagerFileStat[],
		history: FileManagerHistoryMode,
	) => boolean;
	failListing: (requestId: number, error: string) => boolean;
	dismissOperationFeedback: () => void;
	finishOperation: (
		requestId: number,
		operation: FileManagerOperation,
		outcome: FileManagerOperationOutcome,
		options?: { error?: unknown; result?: FileManagerOperationResult },
	) => void;
	forward: () => void;
	open: (entry: FileManagerFileStat) => void;
	openDialog: (dialog: Exclude<FileManagerDialogState, null>) => void;
	refresh: () => void;
	replaceFileSystem: (fileSystem: FileManagerFileSystem, rootPath: string, initialPath?: string) => void;
	requestNavigate: (path: string, history?: FileManagerHistoryMode) => void;
	requestOperation: (operation: FileManagerOperation) => void;
	select: (path: string, options?: { range?: boolean; toggle?: boolean; visiblePaths?: readonly string[] }) => void;
	selectAll: (paths: readonly string[]) => void;
	setAddress: (value: string) => void;
	setCapabilities: (capabilities: Partial<FileManagerCapabilities>) => void;
	setDialogValue: (value: string) => void;
	setOperationNotice: (notice?: string) => void;
	setPreviewOpen: (open: boolean) => void;
	setPreviewDraft: (draft?: { content: string; path: string }) => void;
	setPreviewSaveError: (path: string, message?: string) => void;
	setQuery: (query: string) => void;
	setSidebarOpen: (open: boolean) => void;
	setSort: (by: FileManagerSortBy, direction?: FileManagerSortDirection) => void;
	setViewMode: (mode: FileManagerViewMode) => void;
	up: () => void;
};

export type CreateFileManagerStoreOptions = {
	capabilities?: Partial<FileManagerCapabilities>;
	fileSystem: FileManagerFileSystem;
	initialPath?: string;
	rootPath?: string;
	viewMode?: FileManagerViewMode;
};

export type FileManagerStore = import('zustand/vanilla').StoreApi<FileManagerStoreState>;

export type FileManagerPreviewRenderProps = {
	entry: FileManagerFileStat;
	fileSystem: FileManagerFileSystem;
	manager: FileManagerRegistry;
	defaultPreview: ReactNode;
};

export type FileManagerAddressBarRenderProps = {
	currentMenu: ReactNode;
	defaultAddressBar: ReactNode;
	disabled: boolean;
	loading: boolean;
	onPathChange: (path: string) => void;
	onValueChange: (value: string) => void;
	onValueCommit: (value: string) => void;
	path: string;
	rootPath: string;
	value: string;
};

import Emittery from 'emittery';
import { createStore } from 'zustand/vanilla';
import { mutative } from 'zustand-mutative';
import {
	getFileManagerOperationAdmissionError,
	normalizeRequestedFileManagerOperation,
} from './file-manager-operation-utils';
import {
	type CreateFileManagerStoreOptions,
	defaultFileManagerCapabilities,
	type FileManagerCapabilities,
	type FileManagerEventMap,
	type FileManagerHistoryMode,
	type FileManagerRequest,
	type FileManagerStoreState,
} from './file-manager-types';
import { getFileManagerParentPath, isFileManagerPathWithinRoot, normalizeFileManagerPath } from './file-manager-utils';

export function createFileManagerStore(options: CreateFileManagerStoreOptions) {
	const rootPath = normalizeFileManagerPath(options.rootPath ?? '/');
	const requestedPath = normalizeFileManagerPath(options.initialPath ?? rootPath);
	const initialPath = isFileManagerPathWithinRoot(requestedPath, rootPath) ? requestedPath : rootPath;
	const events = new Emittery<FileManagerEventMap>();

	return createStore(
		mutative<FileManagerStoreState>((setState, getState) => {
			const emitRequest = (request: FileManagerRequest) => {
				void events.emit('request', request);
			};
			const emitSelection = () => {
				void events.emit('event', { type: 'selection-changed', paths: [...getState().selection.paths] });
			};

			return {
				fileSystem: options.fileSystem,
				rootPath,
				capabilities: { ...defaultFileManagerCapabilities, ...options.capabilities },
				navigation: { path: initialPath, address: initialPath, history: [initialPath], index: 0 },
				listing: { entries: [], status: 'idle', requestId: 0 },
				selection: { paths: [] },
				view: {
					mode: options.viewMode ?? 'list',
					previewOpen: options.capabilities?.preview ?? true,
					query: '',
					sidebarOpen: true,
					sortBy: 'name',
					sortDirection: 'asc',
				},
				operation: { nextRequestId: 0, status: 'idle' },
				preview: {},
				dialog: null,
				events,
				actions: {
					back: () => {
						const { history, index } = getState().navigation;
						if (index <= 0) return;
						emitRequest({ type: 'load', path: history[index - 1], history: { type: 'traverse', index: index - 1 } });
					},
					beginListing: (path) => {
						let requestId = 0;
						setState((state) => {
							state.listing.requestId += 1;
							requestId = state.listing.requestId;
							state.listing.requestedPath = path;
							state.listing.status = 'loading';
							state.listing.error = undefined;
						});
						return requestId;
					},
					cancelOperation: () => {
						const state = getState();
						if (state.operation.status !== 'running' || state.operation.activeRequestId === undefined) return;
						emitRequest({
							type: 'cancel-operation',
							fileSystem: state.fileSystem,
							requestId: state.operation.activeRequestId,
						});
					},
					clearError: () => {
						setState((state) => {
							state.listing.error = undefined;
							state.operation.error = undefined;
							state.operation.notice = undefined;
							if (state.operation.status === 'error') state.operation.status = 'idle';
						});
					},
					closeDialog: () => setState((state) => void (state.dialog = null)),
					completeListing: (requestId, path, entries, history) => {
						if (getState().listing.requestId !== requestId) return false;
						let selectionChanged = false;
						setState((state) => {
							const previousSelection = state.selection.paths;
							const availablePaths = new Set(entries.map((entry) => entry.path));
							const nextSelection =
								state.navigation.path === path ? previousSelection.filter((item) => availablePaths.has(item)) : [];
							state.listing.entries = entries;
							state.listing.status = 'ready';
							state.listing.error = undefined;
							state.listing.requestedPath = undefined;
							state.navigation.path = path;
							state.navigation.address = path;
							applyHistory(state.navigation, path, history);
							selectionChanged =
								previousSelection.length !== nextSelection.length ||
								previousSelection.some((item, index) => item !== nextSelection[index]);
							state.selection.paths = nextSelection;
							if (!nextSelection.includes(state.selection.anchorPath ?? ''))
								state.selection.anchorPath = nextSelection[0];
						});
						void events.emit('event', { type: 'navigated', path });
						if (selectionChanged) emitSelection();
						return true;
					},
					failListing: (requestId, error) => {
						if (getState().listing.requestId !== requestId) return false;
						setState((state) => {
							state.listing.status = 'error';
							state.listing.error = error;
							state.listing.requestedPath = undefined;
						});
						return true;
					},
					dismissOperationFeedback: () => {
						setState((state) => {
							state.operation.feedback = undefined;
							state.operation.error = undefined;
							if (state.operation.status === 'error') state.operation.status = 'idle';
						});
					},
					finishOperation: (requestId, operation, outcome, options = {}) => {
						setState((state) => {
							if (state.operation.status !== 'running' || state.operation.activeRequestId !== requestId) return;
							const operationKind = operation.type;
							state.operation.status = outcome === 'failed' ? 'error' : 'idle';
							state.operation.error = options.error ? getOperationErrorMessage(options.error) : undefined;
							state.operation.active = undefined;
							state.operation.activeRequestId = undefined;
							state.operation.kind = undefined;
							state.operation.feedback = {
								error: options.error,
								operation,
								outcome,
								result: options.result,
							};
							if (operationKind === 'save-text' && state.preview.pendingSavePath) {
								const path = state.preview.pendingSavePath;
								state.preview.pendingSavePath = undefined;
								if (outcome === 'succeeded') {
									if (state.preview.draft?.path === path) state.preview.draft = undefined;
									state.preview.saveError = undefined;
								} else {
									state.preview.saveError = {
										message:
											outcome === 'cancelled'
												? '保存已取消'
												: options.error
													? getOperationErrorMessage(options.error)
													: '保存失败',
										path,
									};
								}
							}
						});
					},
					forward: () => {
						const { history, index } = getState().navigation;
						if (index >= history.length - 1) return;
						emitRequest({ type: 'load', path: history[index + 1], history: { type: 'traverse', index: index + 1 } });
					},
					open: (entry) => {
						const state = getState();
						emitRequest({
							type: 'open',
							directory: state.navigation.path,
							entry,
							fileSystem: state.fileSystem,
							listingRequestId: state.listing.requestId,
							rootPath: state.rootPath,
						});
					},
					openDialog: (dialog) => setState((state) => void (state.dialog = dialog)),
					refresh: () => emitRequest({ type: 'load', path: getState().navigation.path, history: { type: 'none' } }),
					replaceFileSystem: (fileSystem, nextRootPath, nextInitialPath) => {
						const normalizedRoot = normalizeFileManagerPath(nextRootPath);
						const normalizedInitial = normalizeFileManagerPath(nextInitialPath ?? normalizedRoot);
						const path = isFileManagerPathWithinRoot(normalizedInitial, normalizedRoot)
							? normalizedInitial
							: normalizedRoot;
						const hadSelection = getState().selection.paths.length > 0;
						setState((state) => {
							const nextOperationRequestId = state.operation.nextRequestId;
							state.fileSystem = fileSystem;
							state.rootPath = normalizedRoot;
							state.navigation = { path, address: path, history: [path], index: 0 };
							state.listing = { entries: [], status: 'idle', requestId: state.listing.requestId + 1 };
							state.selection = { paths: [] };
							state.operation = { nextRequestId: nextOperationRequestId, status: 'idle' };
							state.preview = {};
							state.dialog = null;
						});
						if (hadSelection) emitSelection();
						emitRequest({ type: 'load', path, history: { type: 'replace' } });
					},
					requestNavigate: (path, history = { type: 'push' }) => {
						const normalized = normalizeFileManagerPath(path);
						if (!isFileManagerPathWithinRoot(normalized, getState().rootPath)) {
							setState((state) => {
								state.listing.error = `路径超出根目录：${normalized}`;
								state.listing.status = 'error';
							});
							return;
						}
						emitRequest({ type: 'load', path: normalized, history });
					},
					requestOperation: (requestedOperation) => {
						if (getState().operation.status === 'running') return;
						const admissionError = getFileManagerOperationAdmissionError(requestedOperation);
						if (admissionError) {
							setState((state) => {
								state.operation.notice = admissionError;
							});
							return;
						}
						const operation = normalizeRequestedFileManagerOperation(requestedOperation);
						setState((state) => {
							state.operation.nextRequestId += 1;
							state.operation = {
								active: operation,
								activeRequestId: state.operation.nextRequestId,
								kind: operation.type,
								nextRequestId: state.operation.nextRequestId,
								status: 'running',
							};
							if (operation.type === 'save-text') {
								state.preview.pendingSavePath = operation.path;
								state.preview.saveError = undefined;
							}
							state.dialog = null;
						});
						const state = getState();
						emitRequest({
							type: 'operation',
							fileSystem: state.fileSystem,
							operation,
							requestId: state.operation.activeRequestId as number,
							rootPath: state.rootPath,
						});
					},
					select: (path, selectOptions = {}) => {
						setState((state) => {
							const visiblePaths = selectOptions.visiblePaths ?? state.listing.entries.map((entry) => entry.path);
							if (selectOptions.range && state.selection.anchorPath) {
								const start = visiblePaths.indexOf(state.selection.anchorPath);
								const end = visiblePaths.indexOf(path);
								if (start >= 0 && end >= 0) {
									const [from, to] = start < end ? [start, end] : [end, start];
									state.selection.paths = visiblePaths.slice(from, to + 1);
									return;
								}
							}
							if (selectOptions.toggle) {
								const index = state.selection.paths.indexOf(path);
								if (index >= 0) state.selection.paths.splice(index, 1);
								else state.selection.paths.push(path);
							} else {
								state.selection.paths = [path];
							}
							state.selection.anchorPath = path;
						});
						emitSelection();
					},
					selectAll: (paths) => {
						setState((state) => {
							state.selection.paths = [...paths];
							state.selection.anchorPath = paths[0];
						});
						emitSelection();
					},
					setAddress: (value) => setState((state) => void (state.navigation.address = value)),
					setCapabilities: (capabilities: Partial<FileManagerCapabilities>) => {
						setState((state) => {
							Object.assign(state.capabilities, capabilities);
							if (!state.capabilities.preview) state.view.previewOpen = false;
						});
					},
					setDialogValue: (value) => {
						setState((state) => {
							if (state.dialog && 'value' in state.dialog) state.dialog.value = value;
							else if (state.dialog?.type === 'transfer') state.dialog.destination = value;
						});
					},
					setOperationNotice: (notice) => {
						setState((state) => {
							state.operation.notice = notice;
						});
					},
					setPreviewDraft: (draft) => setState((state) => void (state.preview.draft = draft)),
					setPreviewOpen: (open) => setState((state) => void (state.view.previewOpen = open)),
					setPreviewSaveError: (path, message) => {
						setState((state) => {
							state.preview.saveError = message ? { message, path } : undefined;
						});
					},
					setQuery: (query) => setState((state) => void (state.view.query = query)),
					setSidebarOpen: (open) => setState((state) => void (state.view.sidebarOpen = open)),
					setSort: (by, direction) => {
						setState((state) => {
							if (state.view.sortBy === by && !direction) {
								state.view.sortDirection = state.view.sortDirection === 'asc' ? 'desc' : 'asc';
							} else {
								state.view.sortBy = by;
								state.view.sortDirection = direction ?? 'asc';
							}
						});
					},
					setViewMode: (mode) => setState((state) => void (state.view.mode = mode)),
					up: () => {
						const state = getState();
						if (state.navigation.path === state.rootPath) return;
						const parent = getFileManagerParentPath(state.navigation.path);
						emitRequest({
							type: 'load',
							path: isFileManagerPathWithinRoot(parent, state.rootPath) ? parent : state.rootPath,
							history: { type: 'push' },
						});
					},
				},
			};
		}),
	);
}

function applyHistory(navigation: FileManagerStoreState['navigation'], path: string, history: FileManagerHistoryMode) {
	if (history.type === 'none') return;
	if (history.type === 'replace') {
		navigation.history = [path];
		navigation.index = 0;
		return;
	}
	if (history.type === 'traverse') {
		navigation.index = Math.max(0, Math.min(history.index, navigation.history.length - 1));
		return;
	}
	if (navigation.history[navigation.index] === path) return;
	navigation.history = navigation.history.slice(0, navigation.index + 1);
	navigation.history.push(path);
	navigation.index = navigation.history.length - 1;
}

function getOperationErrorMessage(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

