import { formatFileManagerBytes, toFileManagerFileTypeInput } from './file-manager-utils';

export type FileManagerListingProps = {
	disabled: boolean;
	dragAndDrop: FileManagerDragAndDropController;
	emptyState?: ReactNode;
	entries: FileManagerFileStat[];
	multiple: boolean;
	onOpen: (entry: FileManagerFileStat) => void;
	onSelect: (entry: FileManagerFileStat, options?: { range?: boolean; toggle?: boolean }) => void;
	selectedPaths: string[];
	visiblePaths: string[];
};

export function FileManagerListing({
	disabled,
	dragAndDrop,
	emptyState,
	entries,
	multiple,
	onOpen,
	onSelect,
	selectedPaths,
	visiblePaths,
}: FileManagerListingProps) {
	const actions = useFileManagerActions();
	const { mode, status, error, sortBy, sortDirection } = useFileManagerStore(
		useShallow((state) => ({
			mode: state.view.mode,
			status: state.listing.status,
			error: state.listing.error,
			sortBy: state.view.sortBy,
			sortDirection: state.view.sortDirection,
		})),
	);
	if (status === 'loading' && entries.length === 0) {
		return (
			<div role='status' className='text-base-content/55 grid min-h-full place-items-center text-xs'>
				正在读取目录…
			</div>
		);
	}
	if (status === 'error' && entries.length === 0) {
		return (
			<div role='alert' className='grid min-h-full place-items-center p-6 text-center'>
				<div>
					<div className='text-error text-sm font-medium'>无法打开目录</div>
					<div className='text-base-content/60 mt-1 max-w-md text-xs'>{error}</div>
					<button type='button' className='btn btn-sm mt-3' onClick={actions.refresh}>
						重试
					</button>
				</div>
			</div>
		);
	}
	if (!entries.length) {
		if (emptyState !== undefined) return emptyState;
		return (
			<div className='grid min-h-full place-items-center p-6 text-center'>
				<div>
					<FolderOpen className='text-base-content/30 mx-auto size-9' />
					<div className='mt-2 text-sm font-medium'>当前目录为空</div>
					<div className='text-base-content/55 mt-1 text-xs'>新建文件、目录或拖入文件开始使用。</div>
				</div>
			</div>
		);
	}
	if (mode === 'grid') {
		return (
			<div data-file-manager-grid='' className='flex flex-wrap content-start items-start gap-2 p-2'>
				{entries.map((entry) => {
					const selected = selectedPaths.includes(entry.path);
					const dropFeedback = dragAndDrop.drop?.path === entry.path ? dragAndDrop.drop : undefined;
					const dropProps = entry.kind === 'directory' ? dragAndDrop.getDropTargetProps(entry) : {};
					return (
						<div
							key={entry.path}
							{...dropProps}
							data-file-manager-entry-path={entry.path}
							data-file-manager-grid-item=''
							data-drop-state={dropFeedback?.state}
							data-drop-target={dropFeedback ? true : undefined}
							className={cn(
								'border-base-300 bg-base-100 data-[drop-state=accepted]:border-info data-[drop-state=accepted]:bg-info/15 data-[drop-state=accepted]:ring-info data-[drop-state=rejected]:border-error/60 data-[drop-state=rejected]:bg-error/10 data-[drop-state=rejected]:ring-error/50 relative h-28 w-36 flex-none rounded-md border p-2 data-[drop-target=true]:ring-1',
								selected ? 'border-primary bg-primary/8' : 'hover:bg-base-200/45',
							)}
							title={dropFeedback?.state === 'rejected' ? dropFeedback.reason : undefined}
							draggable={dragAndDrop.canDrag || undefined}
							onDragEnd={dragAndDrop.finishEntryDrag}
							onDragStart={(event) => dragAndDrop.startEntryDrag(entry, event)}
						>
							{multiple ? (
								<input
									type='checkbox'
									aria-label={`选择 ${entry.name}`}
									className='checkbox checkbox-xs absolute top-2 left-2'
									checked={selected}
									disabled={disabled}
									onChange={() => onSelect(entry, { toggle: true })}
								/>
							) : null}
							<button
								type='button'
								disabled={disabled}
								className={cn(
									'flex size-full min-w-0 flex-col items-center justify-center px-2 text-center',
									multiple && 'pt-4',
								)}
								onClick={(event) => onSelect(entry, { range: event.shiftKey, toggle: event.metaKey || event.ctrlKey })}
								onDoubleClick={() => onOpen(entry)}
								onKeyDown={(event) => {
									if (event.key === 'Enter') {
										event.preventDefault();
										event.stopPropagation();
										onOpen(entry);
									}
								}}
							>
								<FileManagerEntryDisplay
									entry={entry}
									mode='grid'
									defaultDisplay={
										<>
											<FileManagerFileTypeIcon file={toFileManagerFileTypeInput(entry)} className='size-8' />
											<span className='mt-2 line-clamp-2 w-full text-xs font-medium break-all'>{entry.name}</span>
											<span className='text-base-content/45 mt-1 text-[10px]'>
												{entry.kind === 'directory' ? '目录' : formatFileManagerBytes(entry.size)}
											</span>
										</>
									}
								/>
							</button>
						</div>
					);
				})}
			</div>
		);
	}
	const allSelected = entries.length > 0 && entries.every((entry) => selectedPaths.includes(entry.path));
	return (
		<table className='w-full min-w-[42rem] border-collapse text-left text-xs'>
			<thead className='bg-base-200 text-base-content/65 sticky top-0 z-10'>
				<tr className='border-base-300 border-b'>
					{multiple ? (
						<th className='w-9 px-2 py-2'>
							<input
								type='checkbox'
								aria-label='选择当前列表全部项目'
								className='checkbox checkbox-xs'
								checked={allSelected}
								disabled={disabled}
								onChange={() => actions.selectAll(allSelected ? [] : visiblePaths)}
							/>
						</th>
					) : null}
					<SortableHeader label='名称' by='name' active={sortBy === 'name'} direction={sortDirection} />
					<SortableHeader
						label='大小'
						by='size'
						active={sortBy === 'size'}
						direction={sortDirection}
						className='w-28'
					/>
					<th className='w-28 px-3 py-2 font-medium'>类型</th>
					<SortableHeader
						label='修改时间'
						by='mtime'
						active={sortBy === 'mtime'}
						direction={sortDirection}
						className='w-44'
					/>
				</tr>
			</thead>
			<tbody className='divide-base-300 divide-y'>
				{entries.map((entry) => {
					const selected = selectedPaths.includes(entry.path);
					const dropFeedback = dragAndDrop.drop?.path === entry.path ? dragAndDrop.drop : undefined;
					const dropProps = entry.kind === 'directory' ? dragAndDrop.getDropTargetProps(entry) : {};
					return (
						<tr
							key={entry.path}
							{...dropProps}
							data-file-manager-entry-path={entry.path}
							data-drop-state={dropFeedback?.state}
							data-drop-target={dropFeedback ? true : undefined}
							className={cn(
								'data-[drop-state=accepted]:bg-info/15 data-[drop-state=accepted]:ring-info data-[drop-state=rejected]:bg-error/10 data-[drop-state=rejected]:text-base-content/50 data-[drop-state=rejected]:ring-error/50 data-[drop-target=true]:ring-1 data-[drop-target=true]:ring-inset',
								selected ? 'bg-primary/8' : 'hover:bg-base-200/45',
							)}
							title={dropFeedback?.state === 'rejected' ? dropFeedback.reason : undefined}
							draggable={dragAndDrop.canDrag || undefined}
							onDragEnd={dragAndDrop.finishEntryDrag}
							onDragStart={(event) => dragAndDrop.startEntryDrag(entry, event)}
						>
							{multiple ? (
								<td className='px-2 py-1.5'>
									<input
										type='checkbox'
										aria-label={`选择 ${entry.name}`}
										className='checkbox checkbox-xs'
										checked={selected}
										disabled={disabled}
										onChange={() => onSelect(entry, { toggle: true })}
									/>
								</td>
							) : null}
							<td className='min-w-56 px-3 py-1.5'>
								<button
									type='button'
									disabled={disabled}
									className='flex w-full min-w-0 items-center gap-2 text-left'
									onClick={(event) =>
										onSelect(entry, { range: event.shiftKey, toggle: event.metaKey || event.ctrlKey })
									}
									onDoubleClick={() => onOpen(entry)}
									onKeyDown={(event) => {
										if (event.key === 'Enter') {
											event.preventDefault();
											event.stopPropagation();
											onOpen(entry);
										}
									}}
								>
									<FileManagerEntryDisplay
										entry={entry}
										mode='list'
										defaultDisplay={
											<>
												<FileManagerFileTypeIcon file={toFileManagerFileTypeInput(entry)} className='size-4' />
												<span className='min-w-0 flex-1 truncate font-medium'>{entry.name}</span>
											</>
										}
									/>
								</button>
							</td>
							<td className='text-base-content/70 px-3 py-1.5 tabular-nums'>
								{entry.kind === 'directory' ? '—' : formatFileManagerBytes(entry.size)}
							</td>
							<td className='text-base-content/70 px-3 py-1.5'>
								<FileManagerEntryTypeLabel entry={entry} />
							</td>
							<td className='text-base-content/70 px-3 py-1.5 tabular-nums'>
								{entry.mtime ? new Date(entry.mtime).toLocaleString() : '—'}
							</td>
						</tr>
					);
				})}
			</tbody>
		</table>
	);
}

function FileManagerEntryDisplay({
	defaultDisplay,
	entry,
	mode,
}: {
	defaultDisplay: ReactNode;
	entry: FileManagerFileStat;
	mode: 'grid' | 'list';
}) {
	const manager = useFileManagerRegistry();
	const file = manager.fileTypes.resolveInput(toFileManagerFileTypeInput(entry));
	const fileType = manager.fileTypes.resolve(file);
	if (!fileType?.display) return defaultDisplay;
	return renderFileManagerFileType(fileType.display, { defaultDisplay, file, fileType, mode });
}

function FileManagerEntryTypeLabel({ entry }: { entry: FileManagerFileStat }) {
	const manager = useFileManagerRegistry();
	const file = manager.fileTypes.resolveInput(toFileManagerFileTypeInput(entry));
	const fileType = manager.fileTypes.resolve(file);
	return fileType ? getFileManagerFileTypeLabel(fileType, file) : '文件';
}

function SortableHeader({
	active,
	by,
	className,
	direction,
	label,
}: {
	active: boolean;
	by: 'name' | 'size' | 'mtime';
	className?: string;
	direction: 'asc' | 'desc';
	label: string;
}) {
	const actions = useFileManagerActions();
	return (
		<th className={cn('px-3 py-2 font-medium', className)}>
			<button type='button' className='flex items-center gap-1' onClick={() => actions.setSort(by)}>
				{label}
				<ArrowDownAZ
					className={cn('size-3', !active && 'opacity-25', active && direction === 'desc' && 'rotate-180')}
				/>
			</button>
		</th>
	);
}

import type {
	FileManagerOperation,
	FileManagerOperationFeedback,
	FileManagerOperationResult,
} from './file-manager-types';
import { fileManagerOperationHardItemLimit, fileManagerUploadHardFileLimit } from './file-manager-types';
import { getFileManagerParentPath, joinFileManagerPath, normalizeFileManagerPath } from './file-manager-utils';

export type FileManagerOperationRefreshPlan = {
	directories: string[];
	removedPaths: string[];
};

export function getFileManagerOperationRefreshPlan(
	operation: FileManagerOperation,
	result: FileManagerOperationResult | undefined,
): FileManagerOperationRefreshPlan {
	if (!result?.completed.length || operation.type === 'download') return { directories: [], removedPaths: [] };
	const directories = new Set<string>();
	const removedPaths = new Set<string>();
	if (operation.type === 'create-directory' || operation.type === 'create-file' || operation.type === 'upload') {
		directories.add(normalizeFileManagerPath(operation.directory));
	} else if (operation.type === 'copy') {
		directories.add(normalizeFileManagerPath(operation.destination));
	} else if (operation.type === 'move') {
		directories.add(normalizeFileManagerPath(operation.destination));
		for (const path of result.completed) {
			const normalized = normalizeFileManagerPath(path);
			directories.add(getFileManagerParentPath(normalized));
			removedPaths.add(normalized);
		}
	} else if (operation.type === 'delete') {
		for (const path of result.completed) {
			const normalized = normalizeFileManagerPath(path);
			directories.add(getFileManagerParentPath(normalized));
			removedPaths.add(normalized);
		}
	} else if (operation.type === 'rename') {
		const source = normalizeFileManagerPath(operation.path);
		const directory = getFileManagerParentPath(source);
		directories.add(directory);
		if (joinFileManagerPath(directory, operation.name) !== source) removedPaths.add(source);
	} else {
		for (const path of result.completed) directories.add(getFileManagerParentPath(path));
	}
	return { directories: [...directories], removedPaths: [...removedPaths] };
}

export type FileManagerOperationErrorInfo = {
	detail?: string;
	title: string;
};

export function collectFileManagerUploadFiles(files: {
	readonly [index: number]: File | undefined;
	readonly length: number;
}): Pick<Extract<FileManagerOperation, { type: 'upload' }>, 'files' | 'rejected'> {
	const overLimit = files.length > fileManagerUploadHardFileLimit;
	const limit = Math.min(files.length, fileManagerUploadHardFileLimit - (overLimit ? 1 : 0));
	const selected: File[] = [];
	for (let index = 0; index < limit; index += 1) {
		const file = files[index];
		if (file) selected.push(file);
	}
	const omitted = files.length - selected.length;
	return {
		files: selected,
		rejected: omitted ? [{ name: `其余 ${omitted} 个项目`, reason: 'too-many' }] : undefined,
	};
}

export function getFileManagerOperationAdmissionError(operation: FileManagerOperation): string | undefined {
	if ('paths' in operation && operation.paths.length > fileManagerOperationHardItemLimit) {
		return `单次操作最多处理 ${fileManagerOperationHardItemLimit} 个项目`;
	}
	return undefined;
}

export function normalizeRequestedFileManagerOperation(operation: FileManagerOperation): FileManagerOperation {
	if (operation.type !== 'upload') return operation;
	const rejected = operation.rejected ?? [];
	if (operation.files.length + rejected.length <= fileManagerUploadHardFileLimit) return operation;
	const files = operation.files.slice(0, fileManagerUploadHardFileLimit - 1);
	const rejectedItems = rejected.slice(0, Math.max(0, fileManagerUploadHardFileLimit - files.length - 1));
	const omitted = operation.files.length - files.length + rejected.length - rejectedItems.length;
	return {
		...operation,
		files,
		rejected: [...rejectedItems, { name: `其余 ${omitted} 个项目`, reason: 'too-many' }],
	};
}

export function createFileManagerRetryOperation(
	feedback: FileManagerOperationFeedback,
): FileManagerOperation | undefined {
	const { operation, result } = feedback;
	if (!result) return operation;
	const completed = new Set(result.completed);
	if (operation.type === 'upload') {
		const files = operation.files
			.slice(0, fileManagerUploadHardFileLimit)
			.filter((file) => !completed.has(joinFileManagerPath(operation.directory, file.name)));
		return files.length ? { ...operation, files, rejected: undefined } : undefined;
	}
	if (
		operation.type === 'copy' ||
		operation.type === 'move' ||
		operation.type === 'delete' ||
		operation.type === 'download'
	) {
		const paths = operation.paths.filter((path) => !completed.has(path));
		return paths.length ? { ...operation, paths } : undefined;
	}
	if (operation.type === 'create-directory' || operation.type === 'create-file') {
		const path = joinFileManagerPath(operation.directory, operation.name);
		return completed.has(path) ? undefined : operation;
	}
	if (operation.type === 'save-text') return completed.has(operation.path) ? undefined : operation;
	return completed.has(operation.path) ? undefined : operation;
}

export function formatFileManagerOperationError(error: unknown): FileManagerOperationErrorInfo {
	const name = getErrorProperty(error, 'name');
	const code = getErrorProperty(error, 'code');
	const message = error instanceof Error ? error.message : String(error);
	if (name === 'AbortError') return { title: '操作已取消' };
	if (name === 'NotAllowedError' || name === 'SecurityError' || code === 'EACCES' || code === 'EPERM') {
		return { title: '没有完成此操作的权限' };
	}
	if (name === 'QuotaExceededError' || code === 'ENOSPC') return { title: '存储空间不足' };
	if (code === 'ENOENT' || /不存在|not found/i.test(message)) return { title: '文件或目标目录不存在' };
	if (code === 'EEXIST' || /目标已存在|already exists/i.test(message)) return { title: '目标中已存在同名项目' };
	if (name === 'NotSupportedError') return { title: '当前文件系统不支持此操作' };
	if (/超过.*上限|too large/i.test(message)) return { title: '文件超出上传限制', detail: message };
	if (/暂不支持拖入本地目录/.test(message)) return { title: '暂不支持上传本地目录' };
	return { title: message || '文件操作失败' };
}

export function getFileManagerOperationResultCount(result: FileManagerOperationResult | undefined) {
	return { completed: result?.completed.length ?? 0, failed: result?.failed.length ?? 0 };
}

function getErrorProperty(error: unknown, property: 'code' | 'name'): string | undefined {
	if (typeof error !== 'object' || error === null || !(property in error)) return undefined;
	const value = (error as Record<string, unknown>)[property];
	return typeof value === 'string' ? value : undefined;
}

'use client';

import { CheckCircle2, RotateCcw, TriangleAlert, X } from 'lucide-react';
import { useFileManagerActions, useFileManagerStore } from './file-manager-context';
import {
	createFileManagerRetryOperation,
	formatFileManagerOperationError,
	getFileManagerOperationResultCount,
} from './file-manager-operation-utils';

export function FileManagerOperationFeedbackPanel() {
	const feedback = useFileManagerStore((state) => state.operation.feedback);
	const notice = useFileManagerStore((state) => state.operation.notice);
	const actions = useFileManagerActions();
	if (notice) {
		return (
			<section aria-label='拖放操作提示' className='border-warning/35 bg-warning/8 border-t' role='alert'>
				<div className='flex min-h-10 items-center gap-2 px-3 py-2 text-xs'>
					<TriangleAlert aria-hidden='true' className='text-warning size-4 shrink-0' />
					<span className='min-w-0 flex-1'>{notice}</span>
					<button
						type='button'
						aria-label='关闭拖放提示'
						title='关闭拖放提示'
						className='hover:bg-base-200 grid size-6 shrink-0 place-items-center rounded-sm'
						onClick={() => actions.setOperationNotice(undefined)}
					>
						<X aria-hidden='true' className='size-3.5' />
					</button>
				</div>
			</section>
		);
	}
	if (!feedback || feedback.operation.type === 'save-text') return null;
	const counts = getFileManagerOperationResultCount(feedback.result);
	const retry = createFileManagerRetryOperation(feedback);
	const failed = feedback.result?.failed ?? [];
	const failedItems = getFailedOperationItems(failed);
	const error = feedback.error ? formatFileManagerOperationError(feedback.error) : undefined;
	const unsuccessful = feedback.outcome !== 'succeeded' || counts.failed > 0;
	const summary = getFeedbackSummary(feedback.outcome, counts.completed, counts.failed);
	return (
		<section
			aria-label='文件操作结果'
			className={unsuccessful ? 'border-error/35 bg-error/6 border-t' : 'border-success/30 bg-success/6 border-t'}
			role={unsuccessful ? 'alert' : 'status'}
		>
			<div className='flex min-h-10 items-start gap-2 px-3 py-2 text-xs'>
				{unsuccessful ? (
					<TriangleAlert aria-hidden='true' className='text-error mt-0.5 size-4 shrink-0' />
				) : (
					<CheckCircle2 aria-hidden='true' className='text-success mt-0.5 size-4 shrink-0' />
				)}
				<div className='min-w-0 flex-1'>
					<div className='font-medium'>{summary}</div>
					{error ? <div className='text-base-content/75 mt-0.5'>{error.title}</div> : null}
					{failed.length ? (
						<ul className='mt-1 grid gap-0.5' aria-label='失败项目'>
							{failedItems.map(({ item, itemError, key }) => (
								<li key={key} className='flex min-w-0 gap-1.5'>
									<span className='min-w-0 truncate font-mono'>{item.path}</span>
									<span aria-hidden='true'>·</span>
									<span className='text-base-content/75 shrink-0'>{itemError.title}</span>
								</li>
							))}
							{failed.length > 5 ? <li>另有 {failed.length - 5} 个失败项目</li> : null}
						</ul>
					) : null}
				</div>
				{retry ? (
					<button
						type='button'
						className='btn btn-ghost btn-xs shrink-0'
						onClick={() => actions.requestOperation(retry)}
					>
						<RotateCcw aria-hidden='true' className='size-3.5' />
						重试
					</button>
				) : null}
				<button
					type='button'
					aria-label='关闭操作结果'
					title='关闭操作结果'
					className='hover:bg-base-200 grid size-6 shrink-0 place-items-center rounded-sm'
					onClick={actions.dismissOperationFeedback}
				>
					<X aria-hidden='true' className='size-3.5' />
				</button>
			</div>
		</section>
	);
}

function getFailedOperationItems(failed: Array<{ path: string; error: unknown }>) {
	const occurrences = new Map<string, number>();
	return failed.slice(0, 5).map((item) => {
		const itemError = formatFileManagerOperationError(item.error);
		const identity = `${item.path}\0${itemError.title}`;
		const occurrence = (occurrences.get(identity) ?? 0) + 1;
		occurrences.set(identity, occurrence);
		return { item, itemError, key: `${identity}\0${occurrence}` };
	});
}

function getFeedbackSummary(outcome: 'cancelled' | 'failed' | 'succeeded', completed: number, failed: number): string {
	if (outcome === 'cancelled') return completed ? `操作已取消，已完成 ${completed} 项` : '操作已取消';
	if (failed && completed) return `部分完成：成功 ${completed} 项，失败 ${failed} 项`;
	if (failed) return `${failed} 项操作失败`;
	if (outcome === 'failed') return '文件操作失败';
	return completed ? `已完成 ${completed} 项` : '操作已完成';
}

import { getFileManagerOperationAdmissionError } from './file-manager-operation-utils';
import type {
	FileManagerFileStat,
	FileManagerFileSystem,
	FileManagerOperation,
	FileManagerOperationResult,
} from './file-manager-types';
import { fileManagerUploadHardFileLimit } from './file-manager-types';
import {
	getFileManagerBasename,
	getFileManagerParentPath,
	isFileManagerDescendantPath,
	isFileManagerPathWithinRoot,
	joinFileManagerPath,
	normalizeFileManagerPath,
	sanitizeFileManagerStat,
	validateFileManagerName,
} from './file-manager-utils';

export type ExecuteFileManagerOperationOptions = {
	fileSystem: FileManagerFileSystem;
	maxDownloadBytes?: number;
	maxDownloadTotalBytes?: number;
	maxUploadBytes: number;
	maxUploadFiles?: number;
	maxUploadTotalBytes?: number;
	onDownload?: (entry: FileManagerFileStat, data: Uint8Array) => Promise<void> | void;
	operation: FileManagerOperation;
	rootPath: string;
	signal: AbortSignal;
};

export async function executeFileManagerOperation({
	fileSystem,
	maxDownloadBytes = 256 * 1024 * 1024,
	maxDownloadTotalBytes = 512 * 1024 * 1024,
	maxUploadBytes,
	maxUploadFiles = 256,
	maxUploadTotalBytes = 512 * 1024 * 1024,
	onDownload,
	operation,
	rootPath,
	signal,
}: ExecuteFileManagerOperationOptions): Promise<FileManagerOperationResult> {
	const admissionError = getFileManagerOperationAdmissionError(operation);
	if (admissionError) throw new Error(admissionError);
	const result: FileManagerOperationResult = { completed: [], failed: [] };
	if (operation.type === 'create-directory' || operation.type === 'create-file') {
		assertName(operation.name);
		const path = assertWithinRoot(joinFileManagerPath(operation.directory, operation.name), rootPath);
		await assertPathsAbsent(fileSystem, [path], signal);
		if (operation.type === 'create-directory') await fileSystem.mkdir(path, { recursive: false, signal });
		else await fileSystem.writeFile(path, '', { overwrite: false, signal });
		result.completed.push(path);
		return result;
	}
	if (operation.type === 'rename') {
		assertName(operation.name);
		const source = assertMutablePath(operation.path, rootPath);
		const destination = assertWithinRoot(
			joinFileManagerPath(getFileManagerParentPath(source), operation.name),
			rootPath,
		);
		if (source !== destination) {
			await fileSystem.stat(source, { signal });
			await assertPathsAbsent(fileSystem, [destination], signal);
			await fileSystem.rename(source, destination, { overwrite: false, signal });
		}
		result.completed.push(source);
		return result;
	}
	if (operation.type === 'copy' || operation.type === 'move') {
		const destination = assertWithinRoot(operation.destination, rootPath);
		const target = await fileSystem.stat(destination, { signal });
		if (target.kind !== 'directory') throw new Error('目标位置不是目录');
		const jobs: Array<{ source: string; target: string }> = [];
		for (const requestedPath of operation.paths) {
			const source = assertMutablePath(requestedPath, rootPath);
			await fileSystem.stat(source, { signal });
			if (source === destination || isFileManagerDescendantPath(source, destination)) {
				throw new Error('不能将项目复制或移动到自身内部');
			}
			const nextPath = joinFileManagerPath(destination, getFileManagerBasename(source));
			if (nextPath !== source) jobs.push({ source, target: nextPath });
		}
		if (new Set(jobs.map((job) => job.target)).size !== jobs.length) throw new Error('多个项目会写入同一个目标路径');
		await assertPathsAbsent(
			fileSystem,
			jobs.map((job) => job.target),
			signal,
		);
		await runBatch(
			result,
			jobs,
			async ({ source, target: targetPath }) => {
				if (operation.type === 'copy') await fileSystem.copy(source, targetPath, { overwrite: false, signal });
				else await fileSystem.rename(source, targetPath, { overwrite: false, signal });
			},
			(job) => job.source,
			signal,
		);
		return result;
	}
	if (operation.type === 'delete') {
		const paths = operation.paths.map((path) => assertMutablePath(path, rootPath));
		await Promise.all(paths.map((path) => fileSystem.stat(path, { signal })));
		await runBatch(
			result,
			paths,
			(path) => fileSystem.rm(path, { recursive: true, signal }),
			(path) => path,
			signal,
		);
		return result;
	}
	if (operation.type === 'upload') {
		const directory = assertWithinRoot(operation.directory, rootPath);
		const targetDirectory = await fileSystem.stat(directory, { signal });
		if (targetDirectory.kind !== 'directory') throw new Error('上传目标不是目录');
		const fileLimit = normalizeOperationLimit(maxUploadFiles, 256, fileManagerUploadHardFileLimit);
		const totalLimit = normalizeOperationLimit(maxUploadTotalBytes, 512 * 1024 * 1024);
		const perFileLimit = normalizeOperationLimit(maxUploadBytes, 100 * 1024 * 1024);
		const files = operation.files.slice(0, fileLimit);
		const nameCounts = new Map<string, number>();
		for (const file of files) nameCounts.set(file.name, (nameCounts.get(file.name) ?? 0) + 1);
		const jobs: Array<{ file: File; target: string }> = [];
		let acceptedBytes = 0;
		for (const [index, file] of files.entries()) {
			let target = file.name || `文件 ${index + 1}`;
			try {
				assertName(file.name);
				target = joinFileManagerPath(directory, file.name);
				if ((nameCounts.get(file.name) ?? 0) > 1) throw new Error(`上传列表包含重复文件名：${file.name}`);
				if (!Number.isFinite(file.size) || file.size < 0) throw new Error(`${file.name} 的文件大小无效`);
				if (file.size > perFileLimit)
					throw new Error(`${file.name} 超过单文件上传上限 ${formatBytesForError(perFileLimit)}`);
				if (acceptedBytes + file.size > totalLimit)
					throw new Error(`上传总大小超过上限 ${formatBytesForError(totalLimit)}`);
				acceptedBytes += file.size;
				jobs.push({ file, target });
			} catch (error) {
				result.failed.push({ path: target, error });
			}
		}
		if (operation.files.length > files.length) {
			result.failed.push({
				path: `其余 ${operation.files.length - files.length} 个文件`,
				error: new Error(`上传文件数量超过上限 ${fileLimit}`),
			});
		}
		const rejectedLimit = Math.max(0, fileLimit - files.length);
		const rejectedItems = operation.rejected?.slice(0, rejectedLimit) ?? [];
		for (const rejected of rejectedItems) {
			result.failed.push({
				path: rejected.name,
				error: new Error(formatRejectedUploadReason(rejected.reason)),
			});
		}
		if ((operation.rejected?.length ?? 0) > rejectedItems.length) {
			result.failed.push({
				path: `其余 ${(operation.rejected?.length ?? 0) - rejectedItems.length} 个项目`,
				error: new Error(`拖入项目数量超过上限 ${fileLimit}`),
			});
		}
		await runBatch(
			result,
			jobs,
			async ({ file, target }) => {
				await assertPathsAbsent(fileSystem, [target], signal);
				await fileSystem.writeFile(target, file.stream(), { overwrite: false, signal });
			},
			(job) => job.target,
			signal,
		);
		return result;
	}
	if (operation.type === 'save-text') {
		const path = assertMutablePath(operation.path, rootPath);
		await fileSystem.writeFile(path, operation.content, { overwrite: true, signal });
		result.completed.push(path);
		return result;
	}
	const perDownloadLimit = normalizeOperationLimit(maxDownloadBytes, 256 * 1024 * 1024, 1024 * 1024 * 1024);
	const totalDownloadLimit = normalizeOperationLimit(maxDownloadTotalBytes, 512 * 1024 * 1024, 1024 * 1024 * 1024);
	let downloadedBytes = 0;
	for (const path of operation.paths) {
		const safePath = assertWithinRoot(path, rootPath);
		try {
			const rawEntry = await fileSystem.stat(safePath, { signal });
			const entry = sanitizeFileManagerStat(rawEntry, safePath);
			if (entry.kind === 'directory') continue;
			const remainingBytes = Math.max(0, totalDownloadLimit - downloadedBytes);
			const allowedBytes = Math.min(perDownloadLimit, remainingBytes);
			if (entry.size > allowedBytes) {
				throw new Error(
					entry.size > perDownloadLimit
						? `${entry.name} 超过单文件下载上限 ${formatBytesForError(perDownloadLimit)}`
						: `下载总大小超过上限 ${formatBytesForError(totalDownloadLimit)}`,
				);
			}
			const data = await fileSystem.readFile(safePath, {
				encoding: 'binary',
				maxBytes: allowedBytes + 1,
				signal,
			});
			if (data.byteLength > allowedBytes) {
				throw new Error(
					allowedBytes < perDownloadLimit
						? `下载总大小超过上限 ${formatBytesForError(totalDownloadLimit)}`
						: `${entry.name} 超过单文件下载上限 ${formatBytesForError(perDownloadLimit)}`,
				);
			}
			downloadedBytes += data.byteLength;
			if (onDownload) await onDownload(entry, data);
			else downloadInBrowser(entry, data);
			result.completed.push(safePath);
		} catch (error) {
			if (isAbortError(error) || signal.aborted) throw new FileManagerOperationCancelledError(result, error);
			result.failed.push({ path: safePath, error });
		}
	}
	if (result.failed.length) throw new FileManagerBatchOperationError(result);
	return result;
}

export class FileManagerBatchOperationError extends Error {
	constructor(public readonly result: FileManagerOperationResult) {
		super(`${result.failed.length} 个项目处理失败`);
		this.name = 'FileManagerBatchOperationError';
	}
}

export class FileManagerOperationCancelledError extends Error {
	constructor(
		public readonly result: FileManagerOperationResult,
		cause?: unknown,
	) {
		super('文件操作已取消', { cause });
		this.name = 'FileManagerOperationCancelledError';
	}
}

async function runBatch<T>(
	result: FileManagerOperationResult,
	items: readonly T[],
	run: (item: T) => Promise<void>,
	getPath: (item: T) => string,
	signal: AbortSignal,
) {
	for (const item of items) {
		const path = getPath(item);
		try {
			await run(item);
			result.completed.push(path);
		} catch (error) {
			if (isAbortError(error) || signal.aborted) throw new FileManagerOperationCancelledError(result, error);
			result.failed.push({ path, error });
		}
	}
	if (result.failed.length) throw new FileManagerBatchOperationError(result);
}

async function assertPathsAbsent(fileSystem: FileManagerFileSystem, paths: readonly string[], signal: AbortSignal) {
	for (const path of paths) {
		try {
			await fileSystem.stat(path, { signal });
		} catch (error) {
			if (isNotFoundError(error)) continue;
			throw error;
		}
		throw new Error(`目标已存在：${path}`);
	}
}

function isNotFoundError(error: unknown): boolean {
	return typeof error === 'object' && error !== null && 'code' in error && error.code === 'ENOENT';
}

function isAbortError(error: unknown): boolean {
	return typeof error === 'object' && error !== null && 'name' in error && error.name === 'AbortError';
}

function assertName(name: string) {
	const error = validateFileManagerName(name);
	if (error) throw new Error(error);
}

function assertWithinRoot(path: string, rootPath: string): string {
	const normalized = normalizeFileManagerPath(path);
	if (!isFileManagerPathWithinRoot(normalized, rootPath)) throw new Error(`路径超出根目录：${normalized}`);
	return normalized;
}

function assertMutablePath(path: string, rootPath: string): string {
	const normalized = assertWithinRoot(path, rootPath);
	if (normalized === normalizeFileManagerPath(rootPath)) throw new Error('不能修改文件管理器根目录');
	return normalized;
}

function downloadInBrowser(entry: FileManagerFileStat, data: Uint8Array) {
	if (typeof document === 'undefined' || typeof URL === 'undefined') throw new Error('当前运行时不支持浏览器下载');
	const url = URL.createObjectURL(new Blob([data.slice().buffer]));
	const anchor = document.createElement('a');
	anchor.href = url;
	anchor.download = entry.name;
	anchor.click();
	queueMicrotask(() => URL.revokeObjectURL(url));
}

function formatBytesForError(bytes: number): string {
	return `${Math.max(1, Math.round(bytes / 1024 / 1024))} MB`;
}

function normalizeOperationLimit(value: number, fallback: number, maximum = Number.MAX_SAFE_INTEGER): number {
	return Number.isFinite(value) ? Math.min(maximum, Math.max(0, Math.floor(value))) : fallback;
}

function formatRejectedUploadReason(reason: 'directory' | 'too-many' | 'unreadable'): string {
	return reason === 'directory'
		? '暂不支持拖入本地目录'
		: reason === 'too-many'
			? '拖入项目数量超过安全上限'
			: '无法读取拖入项目';
}

'use client';

import { useEffect, useRef } from 'react';
import { useFileManagerStoreContext } from './file-manager-context';
import {
	executeFileManagerOperation,
	FileManagerBatchOperationError,
	FileManagerOperationCancelledError,
} from './file-manager-operation-executor';
import type {
	FileManagerCapabilities,
	FileManagerEvent,
	FileManagerFileStat,
	FileManagerFileSystem,
	FileManagerOperation,
	FileManagerOperationResult,
	FileManagerRequest,
} from './file-manager-types';
import { fileManagerListingHardEntryLimit } from './file-manager-types';
import {
	isFileManagerPathWithinRoot,
	joinFileManagerPath,
	normalizeFileManagerPath,
	validateFileManagerName,
} from './file-manager-utils';

export type { ExecuteFileManagerOperationOptions } from './file-manager-operation-executor';
export {
	executeFileManagerOperation,
	FileManagerBatchOperationError,
	FileManagerOperationCancelledError,
} from './file-manager-operation-executor';

export type FileManagerRuntimeProps = {
	fileSystem: FileManagerFileSystem;
	initialPath?: string;
	maxDownloadBytes?: number;
	maxDownloadTotalBytes?: number;
	maxListingEntries?: number;
	maxUploadBytes?: number;
	maxUploadFiles?: number;
	maxUploadTotalBytes?: number;
	rootPath?: string;
	onDownload?: (entry: FileManagerFileStat, data: Uint8Array) => Promise<void> | void;
	onEvent?: (event: FileManagerEvent) => void;
	onOpenFile?: (entry: FileManagerFileStat, fileSystem: FileManagerFileSystem) => Promise<void> | void;
};

export function FileManagerRuntime({
	fileSystem,
	initialPath,
	maxDownloadBytes = 256 * 1024 * 1024,
	maxDownloadTotalBytes = 512 * 1024 * 1024,
	maxListingEntries = 2_000,
	maxUploadBytes = 100 * 1024 * 1024,
	maxUploadFiles = 256,
	maxUploadTotalBytes = 512 * 1024 * 1024,
	rootPath = '/',
	onDownload,
	onEvent,
	onOpenFile,
}: FileManagerRuntimeProps) {
	const store = useFileManagerStoreContext();
	const listingAbort = useRef<AbortController | null>(null);
	const operationAbort = useRef<AbortController | null>(null);
	const backendGeneration = useRef(0);
	const mounted = useRef(true);
	const callbacks = useRef({
		maxDownloadBytes,
		maxDownloadTotalBytes,
		maxListingEntries,
		maxUploadBytes,
		maxUploadFiles,
		maxUploadTotalBytes,
		onDownload,
		onEvent,
		onOpenFile,
	});
	callbacks.current = {
		maxDownloadBytes,
		maxDownloadTotalBytes,
		maxListingEntries,
		maxUploadBytes,
		maxUploadFiles,
		maxUploadTotalBytes,
		onDownload,
		onEvent,
		onOpenFile,
	};

	useEffect(() => {
		mounted.current = true;
		backendGeneration.current += 1;
		listingAbort.current?.abort();
		operationAbort.current?.abort();
		const state = store.getState();
		if (state.fileSystem !== fileSystem || state.rootPath !== normalizeFileManagerPath(rootPath)) {
			state.actions.replaceFileSystem(fileSystem, rootPath, initialPath);
		}
		return () => {
			mounted.current = false;
			backendGeneration.current += 1;
			const current = store.getState();
			if (
				current.operation.status === 'running' &&
				current.operation.active &&
				current.operation.activeRequestId !== undefined
			) {
				current.actions.finishOperation(current.operation.activeRequestId, current.operation.active, 'cancelled');
			}
			listingAbort.current?.abort();
			operationAbort.current?.abort();
		};
	}, [fileSystem, initialPath, rootPath, store]);

	useEffect(() => {
		const events = store.getState().events;
		const offEvent = events.on('event', ({ data }) => callbacks.current.onEvent?.(data));
		const offRequest = events.on('request', ({ data }) => void handleRequest(data));

		async function load(request: Extract<FileManagerRequest, { type: 'load' }>) {
			const state = store.getState();
			const generation = backendGeneration.current;
			const path = normalizeFileManagerPath(request.path);
			if (!isFileManagerPathWithinRoot(path, state.rootPath)) {
				const error = new Error(`Path escapes root: ${path}`);
				void events.emit('event', { type: 'error', action: 'navigate', error });
				return;
			}
			listingAbort.current?.abort();
			const controller = new AbortController();
			listingAbort.current = controller;
			const requestId = state.actions.beginListing(path);
			try {
				const entries = await state.fileSystem.readdir(path, { signal: controller.signal });
				if (!isCurrent(generation, controller.signal)) return;
				const maxEntries = normalizeOperationLimit(
					callbacks.current.maxListingEntries,
					2_000,
					fileManagerListingHardEntryLimit,
				);
				state.actions.completeListing(
					requestId,
					path,
					sanitizeFileManagerEntries(entries, path, state.rootPath, maxEntries),
					request.history,
				);
			} catch (error) {
				if (!isCurrent(generation, controller.signal)) return;
				if (state.actions.failListing(requestId, getErrorMessage(error))) {
					void events.emit('event', { type: 'error', action: 'navigate', error });
				}
			}
		}

		function isCurrent(generation: number, signal: AbortSignal) {
			return mounted.current && !signal.aborted && generation === backendGeneration.current;
		}

		async function handleRequest(request: FileManagerRequest) {
			if (request.type === 'cancel-operation') {
				const current = store.getState();
				if (request.fileSystem === current.fileSystem && request.requestId === current.operation.activeRequestId) {
					operationAbort.current?.abort();
				}
				return;
			}
			if (request.type === 'load') {
				await load(request);
				return;
			}
			if (request.type === 'open') {
				const generation = backendGeneration.current;
				if (!isCurrentOpenRequest(request, generation)) return;
				if (request.entry.kind === 'directory') {
					await load({ type: 'load', path: request.entry.path, history: { type: 'push' } });
					return;
				}
				try {
					await callbacks.current.onOpenFile?.(request.entry, request.fileSystem);
					if (!isCurrentOpenRequest(request, generation)) return;
					void events.emit('event', { type: 'opened', entry: request.entry });
				} catch (error) {
					if (!isCurrentOpenRequest(request, generation)) return;
					void events.emit('event', { type: 'open-failed', entry: request.entry, error });
					void events.emit('event', { type: 'error', action: 'open', error });
				}
				return;
			}
			const state = store.getState();
			if (request.fileSystem !== state.fileSystem || request.rootPath !== state.rootPath) {
				void events.emit('event', {
					type: 'operation-cancelled',
					operation: request.operation,
					reason: 'backend-changed',
				});
				return;
			}
			await runOperation(request.requestId, request.operation, request.fileSystem, request.rootPath);
		}

		function isCurrentOpenRequest(request: Extract<FileManagerRequest, { type: 'open' }>, generation: number) {
			const current = store.getState();
			const directory = normalizeFileManagerPath(request.directory);
			return (
				mounted.current &&
				generation === backendGeneration.current &&
				request.fileSystem === current.fileSystem &&
				normalizeFileManagerPath(request.rootPath) === current.rootPath &&
				request.listingRequestId === current.listing.requestId &&
				directory === current.navigation.path &&
				request.entry.directory === directory &&
				isFileManagerPathWithinRoot(request.entry.path, current.rootPath)
			);
		}

		async function runOperation(
			requestId: number,
			operation: FileManagerOperation,
			requestFileSystem: FileManagerFileSystem,
			requestRootPath: string,
		) {
			const state = store.getState();
			const generation = backendGeneration.current;
			operationAbort.current?.abort();
			const controller = new AbortController();
			operationAbort.current = controller;
			let terminal = false;
			const cancel = (reason: 'aborted' | 'backend-changed', result?: FileManagerOperationResult) => {
				if (terminal) return;
				terminal = true;
				const current = store.getState();
				if (current.operation.status === 'running' && current.operation.activeRequestId === requestId) {
					current.actions.finishOperation(requestId, operation, 'cancelled', { result });
				}
				void events.emit('event', { type: 'operation-cancelled', operation, reason, result });
			};
			try {
				assertOperationCapability(operation, state.capabilities);
				void events.emit('event', { type: 'operation-started', operation });
				const result = await executeFileManagerOperation({
					fileSystem: requestFileSystem,
					maxDownloadBytes: callbacks.current.maxDownloadBytes,
					maxDownloadTotalBytes: callbacks.current.maxDownloadTotalBytes,
					maxUploadBytes: callbacks.current.maxUploadBytes,
					maxUploadFiles: callbacks.current.maxUploadFiles,
					maxUploadTotalBytes: callbacks.current.maxUploadTotalBytes,
					onDownload: callbacks.current.onDownload,
					operation,
					rootPath: requestRootPath,
					signal: controller.signal,
				});
				if (!isCurrent(generation, controller.signal)) {
					cancel(generation === backendGeneration.current ? 'aborted' : 'backend-changed', result);
					return;
				}
				terminal = true;
				state.actions.finishOperation(requestId, operation, 'succeeded', { result });
				void events.emit('event', { type: 'operation-succeeded', operation, result });
				await load({ type: 'load', path: store.getState().navigation.path, history: { type: 'none' } });
			} catch (error) {
				if (!isCurrent(generation, controller.signal)) {
					cancel(
						generation === backendGeneration.current ? 'aborted' : 'backend-changed',
						error instanceof FileManagerOperationCancelledError ? error.result : undefined,
					);
					return;
				}
				if (error instanceof FileManagerOperationCancelledError) {
					cancel('aborted', error.result);
					return;
				}
				terminal = true;
				state.actions.finishOperation(requestId, operation, 'failed', {
					error,
					result: error instanceof FileManagerBatchOperationError ? error.result : undefined,
				});
				void events.emit('event', {
					type: 'operation-failed',
					operation,
					error,
					result: error instanceof FileManagerBatchOperationError ? error.result : undefined,
				});
				void events.emit('event', { type: 'error', action: operation.type, error });
				if (operation.type !== 'download' && operation.type !== 'save-text') {
					await load({ type: 'load', path: store.getState().navigation.path, history: { type: 'none' } });
				}
			}
		}

		void handleRequest({ type: 'load', path: store.getState().navigation.path, history: { type: 'replace' } });
		return () => {
			offEvent();
			offRequest();
			listingAbort.current?.abort();
			operationAbort.current?.abort();
		};
	}, [store]);

	return null;
}

export function sanitizeFileManagerEntries(
	entries: FileManagerFileStat[],
	directory: string,
	rootPath: string,
	maxEntries = 2_000,
): FileManagerFileStat[] {
	if (!Array.isArray(entries)) throw new Error('文件系统返回了无效目录列表');
	if (entries.length > maxEntries) throw new Error(`目录项目数量超过列表上限 ${maxEntries}`);
	const normalizedDirectory = normalizeFileManagerPath(directory);
	const names = new Set<string>();
	return entries.map((entry) => {
		if (validateFileManagerName(entry.name)) throw new Error(`文件系统返回了非法项目名称：${entry.name}`);
		if (names.has(entry.name)) throw new Error(`文件系统返回了重复项目：${entry.name}`);
		names.add(entry.name);
		if (entry.kind !== 'directory' && entry.kind !== 'file')
			throw new Error(`文件系统返回了非法项目类型：${entry.name}`);
		const path = joinFileManagerPath(normalizedDirectory, entry.name);
		if (!isFileManagerPathWithinRoot(path, rootPath)) throw new Error(`文件系统项目超出根目录：${entry.name}`);
		return {
			directory: normalizedDirectory,
			kind: entry.kind,
			meta: entry.meta ?? {},
			mtime: Number.isFinite(entry.mtime) ? entry.mtime : 0,
			name: entry.name,
			path,
			size: Number.isFinite(entry.size) && entry.size > 0 ? entry.size : 0,
		};
	});
}

function assertOperationCapability(operation: FileManagerOperation, capabilities: FileManagerCapabilities) {
	const capability: keyof FileManagerCapabilities = {
		copy: 'copy',
		'create-directory': 'createDirectory',
		'create-file': 'createFile',
		delete: 'delete',
		download: 'download',
		move: 'move',
		rename: 'rename',
		'save-text': 'edit',
		upload: 'upload',
	}[operation.type] as keyof FileManagerCapabilities;
	if (!capabilities[capability]) throw new Error(`Operation is disabled: ${operation.type}`);
}

function normalizeOperationLimit(value: number, fallback: number, maximum = Number.MAX_SAFE_INTEGER): number {
	return Number.isFinite(value) ? Math.min(maximum, Math.max(0, Math.floor(value))) : fallback;
}

function getErrorMessage(error: unknown): string {
	if (error instanceof FileManagerBatchOperationError) {
		return `${error.message}：${error.result.failed.map((item) => `${item.path} (${getErrorMessage(item.error)})`).join('；')}`;
	}
	return error instanceof Error ? error.message : String(error);
}

'use client';

