export type FileManagerSurfaceProps = Omit<ComponentPropsWithRef<'section'>, 'title'> & {
	emptyState?: ReactNode;
	filterEntry?: FileManagerProps['filterEntry'];
	footer?: ReactNode;
	maxPreviewBytes?: number;
	onActivateEntry?: FileManagerProps['onActivateEntry'];
	places?: FileManagerPlace[];
	renderAddressBar?: FileManagerProps['renderAddressBar'];
	renderPreview?: FileManagerProps['renderPreview'];
	selectionMode: NonNullable<FileManagerProps['selectionMode']>;
	showHeader: boolean;
	showFileTree: boolean;
	surfaceVariant: FileManagerSurfaceVariant;
	title: ReactNode;
	treeDirectoriesOnly: boolean;
};

export function FileManagerSurface({
	className,
	emptyState,
	filterEntry,
	footer,
	maxPreviewBytes,
	onActivateEntry,
	onKeyDown,
	places,
	renderAddressBar,
	renderPreview,
	selectionMode,
	showHeader,
	showFileTree,
	surfaceVariant,
	tabIndex,
	title,
	treeDirectoriesOnly,
	...props
}: FileManagerSurfaceProps) {
	const actions = useFileManagerActions();
	const listing = useFileManagerListing();
	const state = useFileManagerStore((current) => current);
	const panelId = useId();
	const previewPanelRef = useRef<PanelImperativeHandle | null>(null);
	const sidebarPanelRef = useRef<PanelImperativeHandle | null>(null);
	const workspaceRef = useRef<HTMLDivElement>(null);
	const embeddedSearchRef = useRef<HTMLInputElement>(null);
	const uploadRef = useRef<HTMLInputElement>(null);
	const [panelOrientation, setPanelOrientation] = useState<'horizontal' | 'vertical'>('vertical');
	const [compactNavigation, setCompactNavigation] = useState(false);
	const [embeddedSearchOpen, setEmbeddedSearchOpen] = useState(false);
	const visibleEntries = useMemo(() => {
		const query = listing.query.trim().toLocaleLowerCase();
		const allowed = filterEntry ? listing.entries.filter(filterEntry) : listing.entries;
		const filtered = query ? allowed.filter((entry) => entry.name.toLocaleLowerCase().includes(query)) : allowed;
		return sortFileManagerEntries(filtered, { by: listing.sortBy, direction: listing.sortDirection });
	}, [filterEntry, listing.entries, listing.query, listing.sortBy, listing.sortDirection]);
	const visiblePaths = useMemo(() => visibleEntries.map((entry) => entry.path), [visibleEntries]);
	const entryByPath = useMemo(() => new Map(listing.entries.map((entry) => [entry.path, entry])), [listing.entries]);
	const selectedEntries = state.selection.paths.flatMap((path) => {
		const entry = entryByPath.get(path);
		return entry ? [entry] : [];
	});
	const selectedEntry = selectedEntries.length === 1 ? selectedEntries[0] : undefined;
	const busy = state.operation.status === 'running';
	const saveRunning = busy && state.operation.kind === 'save-text';
	const isEmbedded = surfaceVariant === 'embedded';
	const dragAndDrop = useFileManagerDragAndDrop({
		busy,
		capabilities: state.capabilities,
		clearIssue: () => actions.setOperationNotice(undefined),
		reportIssue: actions.setOperationNotice,
		requestOperation: actions.requestOperation,
		selectedPaths: state.selection.paths,
		selectPath: (path) => actions.select(path, { visiblePaths }),
	});

	useEffect(() => {
		const element = workspaceRef.current;
		if (!element) return;
		const update = () => {
			const { width } = element.getBoundingClientRect();
			setPanelOrientation(width >= 768 ? 'horizontal' : 'vertical');
			setCompactNavigation(width <= 352);
		};
		update();
		if (typeof ResizeObserver === 'function') {
			const observer = new ResizeObserver(update);
			observer.observe(element);
			return () => observer.disconnect();
		}
		window.addEventListener('resize', update);
		return () => window.removeEventListener('resize', update);
	}, []);

	useEffect(() => {
		if (!isEmbedded || !embeddedSearchOpen) return;
		embeddedSearchRef.current?.focus();
	}, [embeddedSearchOpen, isEmbedded]);

	useEffect(
		() => syncPanel(sidebarPanelRef.current, state.view.sidebarOpen),
		[panelOrientation, state.view.sidebarOpen],
	);
	useEffect(
		() => syncPanel(previewPanelRef.current, state.view.previewOpen),
		[panelOrientation, state.view.previewOpen],
	);

	const openEntry = (entry: FileManagerFileStat) => {
		if (busy) return;
		actions.select(entry.path, { visiblePaths });
		onActivateEntry?.(entry);
		actions.open(entry);
	};
	const selectEntry = (entry: FileManagerFileStat, options?: { range?: boolean; toggle?: boolean }) => {
		actions.select(entry.path, {
			range: selectionMode === 'multiple' && options?.range,
			toggle: selectionMode === 'multiple' && options?.toggle,
			visiblePaths,
		});
	};
	const requestUpload = (files: FileList | File[]) => {
		if (!state.capabilities.upload || busy || files.length === 0) return;
		actions.requestOperation({
			type: 'upload',
			directory: state.navigation.path,
			...collectFileManagerUploadFiles(files),
		});
	};
	const handleKeyboard = (event: KeyboardEvent<HTMLElement>) => {
		if (event.defaultPrevented || busy || isInteractiveTarget(event.target)) return;
		if (selectionMode === 'multiple' && (event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'a') {
			event.preventDefault();
			actions.selectAll(visiblePaths);
		}
		if (event.key === 'Delete' && state.capabilities.delete && selectedEntries.length) {
			event.preventDefault();
			actions.openDialog({ type: 'delete' });
		}
		if (event.key === 'F2' && state.capabilities.rename && selectedEntry) {
			event.preventDefault();
			actions.openDialog({ type: 'rename', value: selectedEntry.name });
		}
		if (event.key === 'Enter' && selectedEntry) {
			event.preventDefault();
			openEntry(selectedEntry);
		}
	};

	return (
		<section
			data-file-manager=''
			data-file-manager-surface={surfaceVariant}
			data-console-density=''
			className={cn(
				'border-base-300 bg-base-100 flex h-[min(48rem,calc(100vh-2rem))] min-h-[32rem] min-w-0 flex-col overflow-hidden rounded-md border',
				className,
			)}
			tabIndex={tabIndex ?? 0}
			onKeyDown={(event) => {
				onKeyDown?.(event);
				handleKeyboard(event);
			}}
			{...props}
		>
			{showHeader && !isEmbedded ? (
				<header className='border-base-300 flex min-h-11 shrink-0 items-center gap-2 border-b px-2.5 py-2'>
					<div className='bg-neutral text-neutral-content grid size-7 shrink-0 place-items-center rounded-md'>
						<FolderOpen className='size-4' />
					</div>
					<h2 className='min-w-0 flex-1 truncate text-sm font-semibold'>{title}</h2>
					<span className='text-base-content/55 hidden text-[11px] sm:inline'>{state.rootPath}</span>
				</header>
			) : null}
			<FileManagerToolbar
				busy={busy}
				compactNavigation={compactNavigation}
				embeddedSearchOpen={embeddedSearchOpen}
				embeddedSearchRef={embeddedSearchRef}
				isEmbedded={isEmbedded}
				listingStatus={listing.status}
				previewPanelRef={previewPanelRef}
				renderAddressBar={renderAddressBar}
				requestUpload={requestUpload}
				saveRunning={saveRunning}
				selectedEntries={selectedEntries}
				selectedEntry={selectedEntry}
				setEmbeddedSearchOpen={setEmbeddedSearchOpen}
				sidebarPanelRef={sidebarPanelRef}
				uploadRef={uploadRef}
			/>
			<FileManagerWorkspace
				busy={busy}
				dragAndDrop={dragAndDrop}
				emptyState={emptyState}
				entries={visibleEntries}
				maxPreviewBytes={maxPreviewBytes}
				onActivateEntry={onActivateEntry}
				onOpen={openEntry}
				onSelect={selectEntry}
				orientation={panelOrientation}
				panelId={panelId}
				places={places}
				previewPanelRef={previewPanelRef}
				renderPreview={renderPreview}
				saveRunning={saveRunning}
				selectedEntry={selectedEntry}
				selectionMode={selectionMode}
				showFileTree={showFileTree}
				sidebarPanelRef={sidebarPanelRef}
				treeDirectoriesOnly={treeDirectoriesOnly}
				visiblePaths={visiblePaths}
				workspaceRef={workspaceRef}
			/>
			<FileManagerOperationFeedbackPanel />
			{footer === undefined ? <DefaultFooter busy={busy} listing={listing} /> : footer}
			<FileManagerDialog dialog={state.dialog} path={state.navigation.path} selectedEntries={selectedEntries} />
		</section>
	);
}

function DefaultFooter({ busy, listing }: { busy: boolean; listing: ReturnType<typeof useFileManagerListing> }) {
	const actions = useFileManagerActions();
	const state = useFileManagerStore((current) => current);
	return (
		<footer className='border-base-300 text-base-content/70 flex min-h-8 shrink-0 items-center gap-3 border-t px-2.5 text-[11px]'>
			<span>{listing.entries.length} 个项目</span>
			{state.selection.paths.length ? <span>已选择 {state.selection.paths.length} 个</span> : null}
			<span className='min-w-0 flex-1 truncate'>
				{listing.requesting ?? state.operation.error ?? listing.error ?? ''}
			</span>
			{busy ? (
				<>
					<span role='status'>正在执行 {getOperationLabel(state.operation.kind)}…</span>
					<button type='button' className='btn btn-ghost btn-xs' onClick={actions.cancelOperation}>
						取消
					</button>
				</>
			) : null}
		</footer>
	);
}

function syncPanel(panel: PanelImperativeHandle | null, open: boolean) {
	if (!panel || panel.isCollapsed() === !open) return;
	if (open) panel.expand();
	else panel.collapse();
}

function getOperationLabel(type: FileManagerOperation['type'] | undefined): string {
	return {
		copy: '复制',
		'create-directory': '新建目录',
		'create-file': '新建文件',
		delete: '删除',
		download: '下载',
		move: '移动',
		rename: '重命名',
		'save-text': '保存',
		upload: '上传',
	}[type ?? 'upload'];
}

function isInteractiveTarget(target: EventTarget | null): boolean {
	return (
		target instanceof HTMLElement &&
		Boolean(target.closest('a, button, input, select, summary, textarea, [contenteditable="true"], [role="button"]'))
	);
}

'use client';

import { PathAddressBar } from '@components/path-address-bar';
import { PathAddressBarMenuItem } from '@components/path-address-bar/path-address-bar-menu-item';
import {
	ArrowLeft,
	ArrowRight,
	ArrowUp,
	Copy,
	Download,
	FilePlus2,
	FolderPlus,
	Grid2X2,
	List,
	Move,
	PanelLeftClose,
	PanelLeftOpen,
	PanelRightClose,
	PanelRightOpen,
	Pencil,
	RefreshCw,
	Search,
	Trash2,
	Upload,
	X,
} from 'lucide-react';
import type { RefObject } from 'react';
import type { PanelImperativeHandle } from 'react-resizable-panels';
import { cn } from '@/lib/utils';
import type { FileManagerProps } from './file-manager';
import { useFileManagerActions, useFileManagerStore } from './file-manager-context';
import { FileManagerCommandButton, FileManagerNavigationButton, FileManagerViewButton } from './file-manager-controls';
import type { FileManagerFileStat } from './file-manager-types';

export type FileManagerToolbarProps = {
	busy: boolean;
	compactNavigation: boolean;
	embeddedSearchOpen: boolean;
	embeddedSearchRef: RefObject<HTMLInputElement | null>;
	isEmbedded: boolean;
	listingStatus: 'error' | 'idle' | 'loading' | 'ready';
	previewPanelRef: RefObject<PanelImperativeHandle | null>;
	renderAddressBar?: FileManagerProps['renderAddressBar'];
	requestUpload: (files: FileList | File[]) => void;
	saveRunning: boolean;
	selectedEntries: FileManagerFileStat[];
	selectedEntry?: FileManagerFileStat;
	setEmbeddedSearchOpen: (open: boolean) => void;
	sidebarPanelRef: RefObject<PanelImperativeHandle | null>;
	uploadRef: RefObject<HTMLInputElement | null>;
};

export function FileManagerToolbar({
	busy,
	compactNavigation,
	embeddedSearchOpen,
	embeddedSearchRef,
	isEmbedded,
	listingStatus,
	previewPanelRef,
	renderAddressBar,
	requestUpload,
	saveRunning,
	selectedEntries,
	selectedEntry,
	setEmbeddedSearchOpen,
	sidebarPanelRef,
	uploadRef,
}: FileManagerToolbarProps) {
	const actions = useFileManagerActions();
	const state = useFileManagerStore((current) => current);
	const canGoBack = state.navigation.index > 0;
	const canGoForward = state.navigation.index < state.navigation.history.length - 1;
	const navigate = (path: string) => actions.requestNavigate(path);
	const currentMenu = (
		<>
			<PathAddressBarMenuItem disabled={busy} onClick={actions.refresh}>
				<RefreshCw aria-hidden='true' className='size-4' />
				<span>刷新目录</span>
			</PathAddressBarMenuItem>
			{state.capabilities.createDirectory ? (
				<PathAddressBarMenuItem
					disabled={busy}
					onClick={() => actions.openDialog({ type: 'create', kind: 'directory', value: '' })}
				>
					<FolderPlus aria-hidden='true' className='size-4' />
					<span>新建目录</span>
				</PathAddressBarMenuItem>
			) : null}
			{state.capabilities.createFile ? (
				<PathAddressBarMenuItem
					disabled={busy}
					onClick={() => actions.openDialog({ type: 'create', kind: 'file', value: '' })}
				>
					<FilePlus2 aria-hidden='true' className='size-4' />
					<span>新建文件</span>
				</PathAddressBarMenuItem>
			) : null}
			{state.capabilities.upload ? (
				<PathAddressBarMenuItem disabled={busy} onClick={() => uploadRef.current?.click()}>
					<Upload aria-hidden='true' className='size-4' />
					<span>上传文件</span>
				</PathAddressBarMenuItem>
			) : null}
			{isEmbedded && selectedEntries.length ? (
				<>
					<div className='bg-base-300 my-1 h-px' />
					<div className='text-base-content/55 px-2 py-1 text-[11px]'>已选择 {selectedEntries.length} 个项目</div>
					{state.capabilities.rename && selectedEntry ? (
						<PathAddressBarMenuItem
							disabled={busy}
							onClick={() => actions.openDialog({ type: 'rename', value: selectedEntry.name })}
						>
							<Pencil aria-hidden='true' className='size-4' />
							<span>重命名</span>
						</PathAddressBarMenuItem>
					) : null}
					{state.capabilities.copy ? (
						<PathAddressBarMenuItem
							disabled={busy}
							onClick={() => actions.openDialog({ type: 'transfer', mode: 'copy', destination: state.navigation.path })}
						>
							<Copy aria-hidden='true' className='size-4' />
							<span>复制到</span>
						</PathAddressBarMenuItem>
					) : null}
					{state.capabilities.move ? (
						<PathAddressBarMenuItem
							disabled={busy}
							onClick={() => actions.openDialog({ type: 'transfer', mode: 'move', destination: state.navigation.path })}
						>
							<Move aria-hidden='true' className='size-4' />
							<span>移动到</span>
						</PathAddressBarMenuItem>
					) : null}
					{state.capabilities.download ? (
						<PathAddressBarMenuItem
							disabled={busy || selectedEntries.some((entry) => entry.kind === 'directory')}
							onClick={() => actions.requestOperation({ type: 'download', paths: [...state.selection.paths] })}
						>
							<Download aria-hidden='true' className='size-4' />
							<span>下载</span>
						</PathAddressBarMenuItem>
					) : null}
					{state.capabilities.delete ? (
						<PathAddressBarMenuItem
							className='text-error'
							disabled={busy}
							onClick={() => actions.openDialog({ type: 'delete' })}
						>
							<Trash2 aria-hidden='true' className='size-4' />
							<span>删除</span>
						</PathAddressBarMenuItem>
					) : null}
				</>
			) : null}
		</>
	);
	const defaultAddressBar = (
		<PathAddressBar
			aria-label='文件路径地址栏'
			className='mx-1 h-8 min-w-0 flex-1'
			currentMenu={currentMenu}
			disabled={busy}
			loading={listingStatus === 'loading'}
			messages={{ inputLabel: '当前位置' }}
			path={state.navigation.path}
			rootLabel='根目录'
			rootPath={state.rootPath}
			value={state.navigation.address}
			onPathChange={navigate}
			onValueChange={actions.setAddress}
			onValueCommit={navigate}
		/>
	);
	const addressBar =
		renderAddressBar?.({
			currentMenu,
			defaultAddressBar,
			disabled: busy,
			loading: listingStatus === 'loading',
			onPathChange: navigate,
			onValueChange: actions.setAddress,
			onValueCommit: navigate,
			path: state.navigation.path,
			rootPath: state.rootPath,
			value: state.navigation.address,
		}) ?? defaultAddressBar;
	return (
		<>
			<div
				data-slot='file-manager-navigation'
				className='border-base-300 bg-base-200/45 flex min-h-11 shrink-0 items-center gap-1 border-b px-2 py-1.5'
			>
				<FileManagerNavigationButton label='后退' disabled={!canGoBack || busy} onClick={actions.back}>
					<ArrowLeft className='size-4' />
				</FileManagerNavigationButton>
				<FileManagerNavigationButton label='前进' disabled={!canGoForward || busy} onClick={actions.forward}>
					<ArrowRight className='size-4' />
				</FileManagerNavigationButton>
				<FileManagerNavigationButton
					label='上一级'
					disabled={state.navigation.path === state.rootPath || busy}
					onClick={actions.up}
				>
					<ArrowUp className='size-4' />
				</FileManagerNavigationButton>
				{!isEmbedded || !compactNavigation ? (
					<FileManagerNavigationButton label='刷新' disabled={busy} onClick={actions.refresh}>
						<RefreshCw className={cn('size-4', listingStatus === 'loading' && 'animate-spin')} />
					</FileManagerNavigationButton>
				) : null}
				{isEmbedded && embeddedSearchOpen ? (
					<label className='border-base-300 bg-base-100 mx-1 flex h-8 min-w-0 flex-1 items-center gap-1.5 rounded-md border px-2'>
						<Search aria-hidden='true' className='text-base-content/45 size-3.5 shrink-0' />
						<input
							ref={embeddedSearchRef}
							aria-label='搜索当前目录'
							placeholder='搜索当前目录'
							className='min-w-0 flex-1 bg-transparent text-xs outline-none'
							value={state.view.query}
							onChange={(event) => actions.setQuery(event.target.value)}
						/>
						<button
							type='button'
							aria-label='关闭搜索'
							title='关闭搜索'
							className='hover:bg-base-200 grid size-6 place-items-center rounded-sm'
							onClick={() => setEmbeddedSearchOpen(false)}
						>
							<X aria-hidden='true' className='size-3.5' />
						</button>
					</label>
				) : (
					addressBar
				)}
				{isEmbedded ? (
					<EmbeddedViewControls
						busy={busy}
						embeddedSearchOpen={embeddedSearchOpen}
						previewPanelRef={previewPanelRef}
						saveRunning={saveRunning}
						setEmbeddedSearchOpen={setEmbeddedSearchOpen}
						sidebarPanelRef={sidebarPanelRef}
					/>
				) : null}
			</div>
			{isEmbedded ? (
				<UploadInput requestUpload={requestUpload} uploadRef={uploadRef} />
			) : (
				<CommandToolbar
					busy={busy}
					previewPanelRef={previewPanelRef}
					requestUpload={requestUpload}
					saveRunning={saveRunning}
					selectedEntries={selectedEntries}
					selectedEntry={selectedEntry}
					sidebarPanelRef={sidebarPanelRef}
					uploadRef={uploadRef}
				/>
			)}
		</>
	);
}

function EmbeddedViewControls({
	busy,
	embeddedSearchOpen,
	previewPanelRef,
	saveRunning,
	setEmbeddedSearchOpen,
	sidebarPanelRef,
}: Pick<
	FileManagerToolbarProps,
	'busy' | 'embeddedSearchOpen' | 'previewPanelRef' | 'saveRunning' | 'setEmbeddedSearchOpen' | 'sidebarPanelRef'
>) {
	const actions = useFileManagerActions();
	const state = useFileManagerStore((current) => current);
	return (
		<>
			<FileManagerNavigationButton
				label='搜索当前目录'
				active={embeddedSearchOpen || Boolean(state.view.query)}
				disabled={busy}
				onClick={() => setEmbeddedSearchOpen(true)}
			>
				<Search className='size-4' />
			</FileManagerNavigationButton>
			<FileManagerNavigationButton
				label={state.view.sidebarOpen ? '关闭位置面板' : '打开位置面板'}
				active={state.view.sidebarOpen}
				onClick={() => togglePanel(sidebarPanelRef, state.view.sidebarOpen, actions.setSidebarOpen)}
			>
				{state.view.sidebarOpen ? <PanelLeftClose className='size-4' /> : <PanelLeftOpen className='size-4' />}
			</FileManagerNavigationButton>
			<div className='border-base-300 flex h-7 items-center rounded-md border p-0.5' aria-label='显示模式'>
				<FileManagerViewButton
					label='列表视图'
