					onClick={() => actions.requestOperation({ type: 'download', paths: [...state.selection.paths] })}
				>
					<Download className='size-4' />
				</FileManagerCommandButton>
			) : null}
			{state.capabilities.delete ? (
				<FileManagerCommandButton
					label='删除'
