					onChange={(event) => actions.setQuery(event.target.value)}
				/>
				{state.view.query ? (
					<button type='button' aria-label='清除搜索' title='清除搜索' onClick={() => actions.setQuery('')}>
						<X className='size-3.5' />
					</button>
				) : null}
			</label>
			<FileManagerNavigationButton
				label={state.view.sidebarOpen ? '关闭位置面板' : '打开位置面板'}
				active={state.view.sidebarOpen}
				onClick={() => togglePanel(sidebarPanelRef, state.view.sidebarOpen, actions.setSidebarOpen)}
			>
				{state.view.sidebarOpen ? <PanelLeftClose className='size-4' /> : <PanelLeftOpen className='size-4' />}
			</FileManagerNavigationButton>
			<div className='border-base-300 flex h-8 items-center rounded-md border p-0.5' aria-label='显示模式'>
				<FileManagerViewButton
					label='列表视图'
					active={state.view.mode === 'list'}
					onClick={() => actions.setViewMode('list')}
				>
					<List className='size-3.5' />
				</FileManagerViewButton>
				<FileManagerViewButton
					label='网格视图'
					active={state.view.mode === 'grid'}
					onClick={() => actions.setViewMode('grid')}
				>
					<Grid2X2 className='size-3.5' />
				</FileManagerViewButton>
			</div>
			{state.capabilities.preview ? (
				<FileManagerNavigationButton
					label={state.view.previewOpen ? '关闭预览' : '打开预览'}
					active={state.view.previewOpen}
					disabled={saveRunning && state.view.previewOpen}
					onClick={() => togglePanel(previewPanelRef, state.view.previewOpen, actions.setPreviewOpen)}
				>
					{state.view.previewOpen ? <PanelRightClose className='size-4' /> : <PanelRightOpen className='size-4' />}
				</FileManagerNavigationButton>
			) : null}
		</div>
	);
}

function UploadInput({ requestUpload, uploadRef }: Pick<FileManagerToolbarProps, 'requestUpload' | 'uploadRef'>) {
	return (
		<input
			ref={uploadRef}
			type='file'
			aria-label='选择上传文件'
			multiple
			className='hidden'
			onChange={(event) => {
				if (event.target.files) requestUpload(event.target.files);
				event.target.value = '';
			}}
		/>
	);
}

function togglePanel(
	panelRef: RefObject<PanelImperativeHandle | null>,
	open: boolean,
	setOpen: (open: boolean) => void,
) {
	const nextOpen = !open;
	setOpen(nextOpen);
	if (nextOpen) panelRef.current?.expand();
	else panelRef.current?.collapse();
}

'use client';

import { useFileManagerRegistry } from '@components/file-viewer/file-manager-registry';
import { ResizableHandle, ResizablePanel, ResizablePanelGroup } from '@ui/resizable';
import { type ReactNode, type RefObject, useRef } from 'react';
import type { PanelImperativeHandle } from 'react-resizable-panels';
import { cn } from '@/lib/utils';
import type { FileManagerProps } from './file-manager';
import { useFileManagerActions, useFileManagerStore } from './file-manager-context';
import type { FileManagerDragAndDropController } from './file-manager-drag-drop';
import { FileManagerListing } from './file-manager-listing';
import { FileManagerPreview } from './file-manager-preview';
import { FileManagerSidebar } from './file-manager-sidebar';
import type { FileManagerFileStat, FileManagerPlace } from './file-manager-types';

export type FileManagerWorkspaceProps = {
	busy: boolean;
	dragAndDrop: FileManagerDragAndDropController;
	emptyState?: ReactNode;
	entries: FileManagerFileStat[];
	maxPreviewBytes?: number;
	onActivateEntry?: FileManagerProps['onActivateEntry'];
	onOpen: (entry: FileManagerFileStat) => void;
	onSelect: (entry: FileManagerFileStat, options?: { range?: boolean; toggle?: boolean }) => void;
	orientation: 'horizontal' | 'vertical';
	panelId: string;
	places?: FileManagerPlace[];
	previewPanelRef: RefObject<PanelImperativeHandle | null>;
	renderPreview?: FileManagerProps['renderPreview'];
	saveRunning: boolean;
	selectedEntry?: FileManagerFileStat;
	selectionMode: 'multiple' | 'single';
	showFileTree: boolean;
	sidebarPanelRef: RefObject<PanelImperativeHandle | null>;
	treeDirectoriesOnly: boolean;
	visiblePaths: string[];
	workspaceRef: RefObject<HTMLDivElement | null>;
};

export function FileManagerWorkspace({
	busy,
	dragAndDrop,
	emptyState,
	entries,
	maxPreviewBytes,
	onActivateEntry,
	onOpen,
	onSelect,
	orientation,
	panelId,
	places,
	previewPanelRef,
	renderPreview,
	saveRunning,
	selectedEntry,
	selectionMode,
	showFileTree,
	sidebarPanelRef,
	treeDirectoriesOnly,
	visiblePaths,
	workspaceRef,
}: FileManagerWorkspaceProps) {
	const manager = useFileManagerRegistry();
	const actions = useFileManagerActions();
	const state = useFileManagerStore((current) => current);
	const sidebarResizeOrientationRef = useRef<string | undefined>(undefined);
	const previewResizeOrientationRef = useRef<string | undefined>(undefined);
	const preview = <FileManagerPreview entry={selectedEntry} manager={manager} maxPreviewBytes={maxPreviewBytes} />;
	const currentDirectoryDropProps = dragAndDrop.getDropTargetProps({
		kind: 'directory',
		path: state.navigation.path,
	});
	return (
		<div ref={workspaceRef} className='min-h-0 min-w-0 flex-1'>
			<ResizablePanelGroup id={`${panelId}-workspace-${orientation}`} orientation={orientation}>
				<ResizablePanel
					id={`${panelId}-places-${orientation}`}
					className='relative'
					style={{ overflow: 'hidden' }}
					collapsible
					collapsedSize={0}
					defaultSize={state.view.sidebarOpen ? (orientation === 'horizontal' ? '15rem' : '42%') : 0}
					minSize={orientation === 'horizontal' ? '11rem' : '30%'}
					maxSize={orientation === 'horizontal' ? '24rem' : '60%'}
					groupResizeBehavior='preserve-pixel-size'
					panelRef={sidebarPanelRef}
					onResize={(size) => {
						if (sidebarResizeOrientationRef.current !== orientation) {
							sidebarResizeOrientationRef.current = orientation;
							return;
						}
						const open = size.inPixels > 0;
						if (open !== state.view.sidebarOpen) actions.setSidebarOpen(open);
					}}
				>
					<div
						className='size-full min-h-0 overflow-hidden'
						aria-hidden={!state.view.sidebarOpen}
						inert={!state.view.sidebarOpen}
					>
						<FileManagerSidebar
							busy={busy}
							directoriesOnly={treeDirectoriesOnly}
							dragAndDrop={dragAndDrop}
							onActivateEntry={onActivateEntry}
							orientation={orientation}
							panelId={panelId}
							places={places}
							showTree={showFileTree}
						/>
					</div>
				</ResizablePanel>
				<ResizableHandle id={`${panelId}-places-handle-${orientation}`} />
				<ResizablePanel
					id={`${panelId}-listing-${orientation}`}
					className='relative'
					style={{ overflow: 'hidden' }}
					defaultSize={orientation === 'vertical' ? '42%' : undefined}
					minSize={orientation === 'horizontal' ? '18rem' : '25%'}
				>
					<div
						{...currentDirectoryDropProps}
						data-file-manager-drop-zone=''
						className='relative h-full min-h-0 min-w-0 overflow-auto'
					>
						<FileManagerListing
							dragAndDrop={dragAndDrop}
							disabled={busy}
							emptyState={emptyState}
							entries={entries}
							multiple={selectionMode === 'multiple'}
							onOpen={onOpen}
							onSelect={onSelect}
							selectedPaths={state.selection.paths}
							visiblePaths={visiblePaths}
						/>
						{dragAndDrop.drop?.path === state.navigation.path ? (
							<div
								className={cn(
									'pointer-events-none absolute inset-1 z-20 grid place-items-center rounded-sm ring-2 ring-inset',
									dragAndDrop.drop.state === 'accepted' ? 'bg-info/12 ring-info' : 'bg-error/10 ring-error/60',
								)}
							>
								<div
									className={cn(
										'bg-base-100/95 rounded-md border px-3 py-2 text-sm font-medium shadow-sm',
										dragAndDrop.drop.state === 'accepted' ? 'border-info/35' : 'border-error/35 text-error',
									)}
								>
									{dragAndDrop.drop.state === 'accepted'
										? `${getDropActionLabel(dragAndDrop.drop.mode)}到当前目录`
										: dragAndDrop.drop.reason}
								</div>
							</div>
						) : null}
					</div>
				</ResizablePanel>
				{state.capabilities.preview ? (
					<>
						<ResizableHandle id={`${panelId}-preview-handle-${orientation}`} disabled={saveRunning} />
						<ResizablePanel
							id={`${panelId}-preview-${orientation}`}
							className='relative'
							style={{ overflow: 'hidden' }}
							collapsible
							collapsedSize={0}
							defaultSize={state.view.previewOpen ? (orientation === 'horizontal' ? '19rem' : '40%') : 0}
							minSize={orientation === 'horizontal' ? '16rem' : '30%'}
							maxSize={orientation === 'horizontal' ? '36rem' : '60%'}
							groupResizeBehavior='preserve-pixel-size'
							disabled={saveRunning}
							panelRef={previewPanelRef}
							onResize={(size) => {
								if (previewResizeOrientationRef.current !== orientation) {
									previewResizeOrientationRef.current = orientation;
									return;
								}
								const open = size.inPixels > 0;
								if (open !== state.view.previewOpen) actions.setPreviewOpen(open);
							}}
						>
							<div
								className='size-full min-h-0 overflow-hidden'
								aria-hidden={!state.view.previewOpen}
								inert={!state.view.previewOpen}
							>
								<aside aria-label='文件预览' className='h-full min-h-0 overflow-hidden'>
									{renderPreview && selectedEntry
										? renderPreview({
												entry: selectedEntry,
												fileSystem: state.fileSystem,
												manager,
												defaultPreview: preview,
											})
										: preview}
								</aside>
							</div>
						</ResizablePanel>
					</>
				) : null}
			</ResizablePanelGroup>
		</div>
	);
}

function getDropActionLabel(mode: 'copy' | 'move' | 'upload'): string {
	return mode === 'copy' ? '复制' : mode === 'move' ? '移动' : '上传';
}

'use client';

import type { FileManagerRegistry } from '@components/file-type-registry/file-manager-file-type-types';
import { FileManagerRegistryProvider, useFileManagerRegistry } from '@components/file-viewer/file-manager-registry';
import type { ComponentPropsWithRef, ReactNode } from 'react';
import { useEffect, useState } from 'react';
import { FileManagerProvider, useFileManagerActions } from './file-manager-context';
import { FileManagerRuntime, type FileManagerRuntimeProps } from './file-manager-runtime';
import { createFileManagerStore } from './file-manager-store';
import { FileManagerSurface, type FileManagerSurfaceProps } from './file-manager-surface';
import type {
	FileManagerAddressBarRenderProps,
	FileManagerCapabilities,
	FileManagerEvent,
	FileManagerFileStat,
	FileManagerFileSystem,
	FileManagerPlace,
	FileManagerPreviewRenderProps,
	FileManagerStore,
	FileManagerViewMode,
} from './file-manager-types';

export type FileManagerProps = Omit<ComponentPropsWithRef<'section'>, 'onError' | 'title'> & {
	capabilities?: Partial<FileManagerCapabilities>;
	emptyState?: ReactNode;
	fileSystem: FileManagerFileSystem;
	filterEntry?: (entry: FileManagerFileStat) => boolean;
	footer?: ReactNode;
	initialPath?: string;
	manager?: FileManagerRegistry;
	maxDownloadBytes?: number;
	maxDownloadTotalBytes?: number;
	maxListingEntries?: number;
	maxPreviewBytes?: number;
	maxUploadBytes?: number;
	maxUploadFiles?: number;
	maxUploadTotalBytes?: number;
	onActivateEntry?: (entry: FileManagerFileStat) => void;
	onDownload?: FileManagerRuntimeProps['onDownload'];
	onEvent?: (event: FileManagerEvent) => void;
	onOpenFile?: FileManagerRuntimeProps['onOpenFile'];
	places?: FileManagerPlace[];
	readOnly?: boolean;
	renderAddressBar?: (props: FileManagerAddressBarRenderProps) => ReactNode;
	renderPreview?: (props: FileManagerPreviewRenderProps) => ReactNode;
	rootPath?: string;
	selectionMode?: 'multiple' | 'single';
	showHeader?: boolean;
	showFileTree?: boolean;
	surfaceVariant?: FileManagerSurfaceVariant;
	store?: FileManagerStore;
	title?: ReactNode;
	treeDirectoriesOnly?: boolean;
	viewMode?: FileManagerViewMode;
};

export type FileManagerSurfaceVariant = 'workspace' | 'embedded';
export { FileManagerSurface } from './file-manager-surface';

export function FileManager({
	capabilities,
	className,
	emptyState,
	fileSystem,
	filterEntry,
	footer,
	initialPath,
	manager: managerOverride,
	maxDownloadBytes,
	maxDownloadTotalBytes,
	maxListingEntries,
	maxPreviewBytes,
	maxUploadBytes,
	maxUploadFiles,
	maxUploadTotalBytes,
	onActivateEntry,
	onDownload,
	onEvent,
	onOpenFile,
	places,
	readOnly = false,
	renderAddressBar,
	renderPreview,
	rootPath = '/',
	selectionMode = 'multiple',
	showHeader = true,
	showFileTree = true,
	surfaceVariant = 'workspace',
	store,
	title = '文件管理器',
	treeDirectoriesOnly = false,
	viewMode,
	...props
}: FileManagerProps) {
	const manager = useFileManagerRegistry(managerOverride);
	const resolvedCapabilities = resolveFileManagerCapabilities(capabilities, readOnly);
	const [localStore] = useState(
		() =>
			store ??
			createFileManagerStore({
				capabilities: resolvedCapabilities,
				fileSystem,
				initialPath,
				rootPath,
				viewMode,
			}),
	);
	const surfaceProps: FileManagerSurfaceProps = {
		className,
		emptyState,
		filterEntry,
		footer,
		maxPreviewBytes,
		onActivateEntry,
		places,
		renderAddressBar,
		renderPreview,
		selectionMode,
		showHeader,
		showFileTree,
		surfaceVariant,
		title,
		treeDirectoriesOnly,
		...props,
	};
	return (
		<FileManagerRegistryProvider manager={manager}>
			<FileManagerProvider store={store ?? localStore}>
				<FileManagerConfiguration capabilities={resolvedCapabilities} />
				<FileManagerRuntime
					fileSystem={fileSystem}
					initialPath={initialPath}
					maxDownloadBytes={maxDownloadBytes}
					maxDownloadTotalBytes={maxDownloadTotalBytes}
					maxListingEntries={maxListingEntries}
					maxUploadBytes={maxUploadBytes}
					maxUploadFiles={maxUploadFiles}
					maxUploadTotalBytes={maxUploadTotalBytes}
					rootPath={rootPath}
					onDownload={onDownload}
					onEvent={onEvent}
					onOpenFile={onOpenFile}
				/>
				<FileManagerSurface {...surfaceProps} />
			</FileManagerProvider>
		</FileManagerRegistryProvider>
	);
}

function FileManagerConfiguration({ capabilities }: { capabilities: FileManagerCapabilities }) {
	const actions = useFileManagerActions();
	useEffect(() => actions.setCapabilities(capabilities), [actions, capabilities]);
	return null;
}

function resolveFileManagerCapabilities(
	capabilities: Partial<FileManagerCapabilities> | undefined,
	readOnly: boolean,
): FileManagerCapabilities {
	const defaults: FileManagerCapabilities = {
		copy: true,
		createDirectory: true,
		createFile: true,
		delete: true,
		download: true,
		edit: true,
		move: true,
		preview: true,
		rename: true,
		upload: true,
	};
	const resolved = { ...defaults, ...capabilities };
	if (!readOnly) return resolved;
	return {
		...resolved,
		copy: false,
		createDirectory: false,
		createFile: false,
		delete: false,
		edit: false,
		move: false,
		rename: false,
		upload: false,
	};
}

'use client';

import type { ReactNode } from 'react';
import { cn } from '@/lib/utils';
import { FileManager, type FileManagerProps } from './file-manager';

export const FILE_MANAGER_WINDOW_KIND = 'file-manager';

export type FileManagerWindowOpenOptions = {
	bounds?: { height?: number; width?: number; x?: number; y?: number };
	capabilities?: Partial<{
		close: boolean;
		fullscreen: boolean;
		maximize: boolean;
		minimize: boolean;
		move: boolean;
		resize: boolean;
	}>;
	chrome?: 'default' | 'none';
	duplicate?: 'focus-existing' | 'replace' | 'allow';
	icon?: string;
	id?: string;
	key?: string;
	mode?: 'normal' | 'minimized' | 'maximized' | 'fullscreen';
	pinned?: boolean;
	showInDock?: boolean;
	size?: { maxHeight?: number; maxWidth?: number; minHeight?: number; minWidth?: number };
	title?: string;
};

export type FileManagerWindowActions = {
	open: (options: {
		bounds?: FileManagerWindowOpenOptions['bounds'];
		capabilities?: FileManagerWindowOpenOptions['capabilities'];
		chrome?: FileManagerWindowOpenOptions['chrome'];
		data: FileManagerWindowData;
		duplicate?: FileManagerWindowOpenOptions['duplicate'];
		icon?: string;
		id?: string;
		key?: string;
		kind: typeof FILE_MANAGER_WINDOW_KIND;
		mode?: FileManagerWindowOpenOptions['mode'];
		persistence: 'none';
		pinned?: boolean;
		showInDock?: boolean;
		size?: FileManagerWindowOpenOptions['size'];
		title: string;
	}) => string;
};

export type ShowFileManagerOptions = {
	fileManager: FileManagerProps;
	window?: FileManagerWindowOpenOptions;
	windowManager: FileManagerWindowActions;
};

export type FileManagerWindowDescriptor = {
	data?: unknown;
	kind: string;
};

export type FileManagerWindowData = {
	fileManager: FileManagerProps;
	type: typeof FILE_MANAGER_WINDOW_KIND;
};

export function showFileManager({ fileManager, window, windowManager }: ShowFileManagerOptions): string {
	const { bounds, size, title: windowTitle, ...windowOptions } = window ?? {};
	const title = windowTitle ?? (typeof fileManager.title === 'string' ? fileManager.title : '文件管理器');
	return windowManager.open({
		key: FILE_MANAGER_WINDOW_KIND,
		icon: 'folder',
		duplicate: 'focus-existing',
		showInDock: true,
		...windowOptions,
		bounds: { width: 960, height: 640, ...bounds },
		data: { type: FILE_MANAGER_WINDOW_KIND, fileManager },
		kind: FILE_MANAGER_WINDOW_KIND,
		persistence: 'none',
		size: { minWidth: 560, minHeight: 420, ...size },
		title,
	});
}

export function renderFileManagerWindow(window: FileManagerWindowDescriptor): ReactNode {
	return isFileManagerWindowData(window.data) && window.kind === FILE_MANAGER_WINDOW_KIND ? (
		<FileManagerWindow data={window.data} />
	) : null;
}

export function FileManagerWindow({ className, data }: { className?: string; data: FileManagerWindowData }) {
	return (
		<FileManager
			{...data.fileManager}
			className={cn('size-full min-h-0 rounded-none border-0', data.fileManager.className, className)}
			showHeader={data.fileManager.showHeader ?? false}
		/>
	);
}

function isFileManagerWindowData(value: unknown): value is FileManagerWindowData {
	if (typeof value !== 'object' || value === null || (value as { type?: unknown }).type !== FILE_MANAGER_WINDOW_KIND)
		return false;
	const fileManager = (value as { fileManager?: unknown }).fileManager;
	if (typeof fileManager !== 'object' || fileManager === null) return false;
	const fileSystem = (fileManager as { fileSystem?: unknown }).fileSystem;
	if (typeof fileSystem !== 'object' || fileSystem === null) return false;
	const methods = fileSystem as Record<string, unknown>;
	return ['copy', 'exists', 'mkdir', 'readFile', 'readdir', 'rename', 'rm', 'stat', 'writeFile'].every(
		(method) => typeof methods[method] === 'function',
	);
}

